window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch11"]={"id": "ch11", "title": "第十一章 分子进化与系统发育", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第十一章 分子进化与系统发育", "slides": [{"i": 0, "sec": "第一节 分子进化与系统发育", "title": "分子进化与系统发育概述", "notes": "本页为第十一章开篇，介绍分子进化与系统发育的基本概念和理论，并概述几种分子系统发育树构建方法的基本原理、构建步骤及常用软件（如MEGA）和在线工具的应用。1859年达尔文出版《物种起源》，提出进化论观点；德国学者海克尔依据进化论绘制“生命之树”，使生命之树成为进化论的标志性概念。由于形态和生理特征进化方式复杂、化石资料不完整，传统“生命之树”存在争议，对分类单元分歧时间等细节含糊不清。DNA等分子序列因相对稳定的进化演变过程和巨大信息量，大大提高了物种间系统发育关系的推断能力。第一节“分子进化与系统发育”指出，20世纪50年代以前，科学家主要通过古生物学、形态学、胚胎发生学、比较解剖学、生物地理学、生理学和遗传学等研究生物进化；50年代以后，随着分子生物学和分子遗传学兴起，开始从分子水平探讨生物进化的原因和机制。在长期进化过程中，生物大分子在分子水平上的变异会被积累，形成与祖先差异很大的生物大分子。因此，核酸和蛋白质分子组成的序列中蕴藏着大量生物进化的遗传信息。根据各种生物间在分子水平上的进化关系，可以建立分子进化的系统发育树，估测物种间的亲缘关系。", "page": 227, "level": "掌握", "img": "assets/img/ch11/p227.jpg", "anim": null, "fig": null, "points": ["达尔文1859年《物种起源》提出进化论，海克尔绘制“生命之树”成为进化论标志性概念。", "传统“生命之树”因形态生理特征进化复杂、化石资料不完整而存在争议。", "分子进化与系统发育利用生物大分子序列差异重建生物间亲缘关系。", "本章概述分子系统发育树构建方法的基本原理、步骤及常用软件（如MEGA）和在线工具。", "⚠️ 考点/易错点：达尔文《物种起源》1859年出版、海克尔绘制“生命之树”是常考年代与人物对应点；注意传统生命之树因形态生理进化复杂、化石不完整而存在争议，分子序列因信息量大且进化相对稳定而成为重建系统发育的重要依据。"], "code": null, "lang": null, "check": {"q": "达尔文出版《物种起源》并提出进化论观点是在哪一年？", "o": ["A. 1859年", "B. 1865年", "C. 1900年", "D. 1953年"], "a": "A", "e": "1859年达尔文出版《物种起源》，提出进化论观点；德国学者海克尔随后依据进化论绘制了“生命之树”。"}, "cards": [{"front": "达尔文出版《物种起源》是哪一年？谁绘制了“生命之树”？", "back": "1859年；德国学者海克尔。", "mnemonic": "达尔文1859，海克尔画树。", "useImg": false}]}, {"i": 1, "sec": "第一节 分子进化与系统发育", "title": "分子进化的特点：进化速率相对恒定与保守性", "notes": "本页阐述分子进化的两个显著特点：进化速率的相对恒定性和进化的保守性。第一，生物大分子进化速率相对恒定。以核酸和蛋白质一级结构分子序列中的核苷酸或氨基酸替换数作为进化改变量，以年为单位，生物大分子随时间的改变即分子进化速率几乎是恒定的。研究表明，生物大分子一级结构的改变或替换只与进化经历的时间相关，而与表型进化速率不相关。一种可能解释是：大分子一级结构中组成单元的替换是一个没有特殊驱动和控制的随机过程。不同物种同源核酸和蛋白质大分子被认为有相同起源。研究这些大分子一级结构的改变，检测不同物种间大分子序列中的核苷酸或氨基酸替换数，再结合地质学化石数据，可确定分子进化速率。Zuckerkandl和Pauling（1965）发现，不同生物系统的同一血红蛋白分子氨基酸随时间以几乎一定比例相互置换，即氨基酸在单位时间以同样速度进行置换，某一蛋白质在不同物种间的取代数与所研究物种间的分歧时间接近正线性关系，进而将分子水平的这种恒速变异称为“分子钟”。第二，生物大分子进化的保守性，指功能上重要的大分子或大分子局部在进化速率上明显低于功能上不重要的大分子或局部。例如，DNA密码子中的同义替换比变义替换发生频率高，因为前者不会引起对应蛋白质分子氨基酸顺序的改变。", "page": 228, "level": "掌握", "img": "assets/img/ch11/p228.jpg", "anim": null, "fig": null, "points": ["分子进化两大特点：进化速率相对恒定和进化的保守性。", "以核苷酸或氨基酸替换数作为进化改变量，分子进化速率随时间几乎恒定。", "生物大分子一级结构的改变只与进化经历的时间相关，与表型进化速率不相关。", "可能解释：大分子一级结构中组成单位多数替换对功能无影响或影响很小。", "⚠️ 考点/易错点：核心考点是分子进化速率相对恒定：生物大分子一级结构的核苷酸或氨基酸替换数只与进化经历的时间相关，而与表型进化速率不相关；易错处是误认为分子进化速率与表型进化速率同步。"], "code": null, "lang": null, "check": {"q": "关于分子进化速率相对恒定性的解释，下列哪项最符合本章观点？", "o": ["A. 大分子一级结构中组成单元的替换受自然选择严格控制", "B. 大分子一级结构中组成单元的替换是一个没有特殊驱动和控制的随机过程", "C. 分子进化速率与表型进化速率高度相关", "D. 分子进化速率完全由环境变化决定"], "a": "B", "e": "研究表明生物大分子一级结构的改变或替换只与进化经历的时间相关，与表型进化速率不相关，一种可能解释是替换是没有特殊驱动和控制的随机过程。"}, "cards": [{"front": "分子进化的两个显著特点是什么？", "back": "进化速率相对恒定和进化的保守性。", "mnemonic": "恒速保守。", "useImg": false}]}, {"i": 2, "sec": "第一节 分子进化与系统发育", "title": "中性学说、基因组计划与分子进化研究意义", "notes": "本页继续讨论分子进化理论，强调遗传漂变和突变压在分子进化中的作用，是对综合进化论的重要补充和修正。中性学说一方面承认自然选择在表型进化中的作用，另一方面强调分子水平上进化现象的特殊性。随后介绍基因组计划与分子进化。人类基因组计划由美国科学家于1985年率先提出，1990年正式启动，美国、英国、法国、德国、日本和中国科学家共同参与，耗资达30亿美元。其主要目的是测出人类基因组DNA的30亿碱基对序列，发现所有人类基因，找出它们在染色体上的位置，破译人类全部遗传信息，解码生命，了解生命起源、生长发育规律，认识种属之间和个体之间差异的起因、疾病产生机制以及长寿与衰老等生命现象，为疾病诊治提供科学依据。基因组计划已基本完成，人类进入“后基因组学”时代。当前基因组学研究重心已从揭示生命所有遗传信息转移到在分子整体水平上对基因功能的研究，标志是产生了功能基因组学。随着生物学技术和计算技术发展，逐渐形成新的全局方法——基因组表达图谱（转录分析，如在mRNA水平上通过DNA芯片技术检测大量基因表达模式）和大规模蛋白质图谱（蛋白组分析）。使用全局方法研究时，同时检测大量基因表达水平，从整体水平获得基因功能及基因间相互作用信息，通过比较不同物种、不同进化水平生物的相关基因，揭示基因在生命系统中的地位和作用，解释整个生命系统的组成和作用方式。最后引出研究分子进化的意义。", "page": 229, "level": "掌握", "img": "assets/img/ch11/p229.jpg", "anim": null, "fig": null, "points": ["中性学说强调遗传漂变和突变压在分子进化中的作用，是对综合进化论的重要补充和修正。", "中性学说承认自然选择在表型进化中的作用，但强调分子水平进化的特殊性。", "人类基因组计划1985年提出，1990年启动，美英法德日中等国参与，耗资30亿美元。", "基因组计划为分子进化研究提供了大量数据，推动了分子进化研究的发展。", "⚠️ 考点/易错点：中性学说强调遗传漂变和突变压在分子进化中的作用，是对综合进化论的重要补充和修正，但并非完全否定自然选择在表型进化中的作用；人类基因组计划1985年提出、1990年启动、耗资30亿美元、六国参与等数字易考。"], "code": null, "lang": null, "check": {"q": "人类基因组计划正式启动于哪一年？", "o": ["A. 1985年", "B. 1990年", "C. 1995年", "D. 2000年"], "a": "B", "e": "人类基因组计划由美国科学家于1985年率先提出，1990年正式启动，美国、英国、法国、德国、日本和中国科学家共同参与。"}, "cards": [{"front": "中性学说的核心观点是什么？", "back": "强调遗传漂变和突变压在分子进化中的作用，是对综合进化论的重要补充和修正。", "mnemonic": "中性漂变突变压。", "useImg": false}]}, {"i": 3, "sec": "第一节 分子进化与系统发育", "title": "系统发育树：有根树与无根树", "notes": "本页介绍系统发育树的基本概念。前提是生物大分子进化速率相对恒定。在研究生物进化和系统分类中，常用一种类似树状分支的图形来概括各种（类）生物之间的亲缘关系，这种树状分支图形称为系统发育树。通过比较生物大分子序列差异的数值构建的系统树称为分子系统树。分支的末端和分支的联结点称为结，代表生物类群，分支末端的结表示仍生存的种类。系统树可能有时间比例，或者用两个结之间的分枝长度变化来表示分子序列的差异数值。系统发育树可分为有根树和无根树两类。有根树是具有方向的树，包含唯一的节点，将其作为树中所有物种的最近共同祖先。最常用的确定树根的方法是使用一个或多个无可争议的同源物种作为“外群”，这个外群要足够近，以提供足够的信息，但又不能太近，以致不能和树中的种类相混。把有根树去掉根即成为无根树。所谓“无根”，是指树系中代表时间上最早的部位（最早的共同祖先）不能确定，只反映分类单元之间的距离而不涉及谁是谁的祖先的问题。一棵无根树在没有其他信息（外群）或假设（如假设最大枝长为根）时不能确定其树根。无根树是没有方向的，其中线段的两个演化方向都有可能。树系的末端代表现代生存的物种，称为顶结，也称为外结或顶端；树内的分支点叫内结；两结之间的连接部分称为分枝或枝，也可称之为节。", "page": 230, "level": "掌握", "img": "assets/img/ch11/p230.jpg", "anim": null, "fig": null, "points": ["系统发育树前提：生物大分子进化速率相对恒定。", "系统发育树是概括生物之间亲缘关系的树状分支图形。", "通过比较生物大分子序列差异数值构建的系统树称为分子系统树。", "分支末端和联结点称为结，代表生物类群；分支末端的结表示仍生存的种类。", "系统树可能有时间比例，或用两个结之间的分支长度表示进化距离。", "⚠️ 考点/易错点：系统发育树的前提是生物大分子进化速率相对恒定；有根树与无根树的区分是易混点：有根树能确定共同祖先和进化方向，无根树只反映类群间亲缘关系而不指明进化方向。"], "code": null, "lang": null, "check": {"q": "关于系统发育树中“结”的描述，正确的是？", "o": ["A. 分支的末端和分支的联结点称为结，代表生物类群", "B. 结只表示仍生存的种类", "C. 结只表示已灭绝的祖先", "D. 结表示分子序列的差异数值"], "a": "A", "e": "分支的末端和分支的联结点称为结，代表生物类群；分支末端的结表示仍生存的种类。系统发育树可分为有根树和无根树。"}, "cards": [{"front": "什么是系统发育树？什么是分子系统树？", "back": "系统发育树是概括生物之间亲缘关系的树状分支图形；通过比较生物大分子序列差异数值构建的系统树称为分子系统树。", "mnemonic": "树状分支亲缘关系，分子序列差异建树。", "useImg": false}]}, {"i": 4, "sec": "第一节 分子进化与系统发育", "title": "全生命系统树与基因组时代的分子进化", "notes": "本页介绍Woese（1998；2000）根据某些代表生物16S rRNA或18S rRNA的序列比较，首次提出一个涵盖整个生命界的系统树，而后又进行多次修改和补充。图11-2是近年提出的一个全生命系统树，勾勒了生物进化的大致轮廓。从图中可以看出，这是有根的树，根部的结代表地球上最先出现的生命，是现有生物的共同祖先，生物最初的进化从这里开始。16S rRNA或18S rRNA序列分析表明，它最初先分成两支：一支发展成为今天的细菌（真细菌）；另一支是古生菌—真核生物分支，在进化过程中进一步分叉，分别发展成古生菌和真核生物。因此，该系统树反映的进化关系表明，古生菌和真核生物属“姊妹群”，它们之间的关系比它们与真细菌之间的关系更加密切。从该系统树中还可以看出，古生菌分支的结点离根部最近，其分支上距离也最短，表明它是现存生物中进化变化最少、最原始的一个类群。真核生物则离共同祖先最远，是进化程度最高的生物种类。图11-2生命系统树展示了细菌域、古生菌域和真核生物域，以及动物、植物、其他细菌、蓝细菌、嗜泉古细菌、广域古细菌、藻类、超嗜热细菌等类群，根部为共同祖先。近年来，随着分子生物学不断发展和基因组测序计划实施，基因组巨量信息推进分子进化研究再次成为生命科学中最引人注目的领域之一，重大问题包括遗传密码的起源、基因组结构的形成与演化、进化的动力、生物进化等。随着越来越多生物基因组测序完成，人们开始从基因组水平探索进化奥秘，发展和深化传统进化思想与分子进化分析方法。由于生命蓝图由DNA书写，可通过比较DNA序列研究不同生物之间的进化关系，构建“进化树”。", "page": 231, "level": "掌握", "img": "assets/img/ch11/p231.jpg", "anim": null, "fig": "图11-2为全生命系统树，从根部向外分支，根部代表共同祖先，分支末端代表现存生物类群；分支长度反映进化距离或时间。", "points": ["Woese（1998；2000）根据16S rRNA或18S rRNA序列比较首次提出涵盖整个生命界的系统树。", "全生命系统树是有根树，根部的结代表地球上最先出现的生命，是现有生物的共同祖先。", "16S rRNA或18S rRNA序列比较是构建全生命系统树的重要依据。", "全生命系统树勾勒了生物进化的大致轮廓，并经过多次修改和补充。", "⚠️ 考点/易错点：Woese根据16S/18S rRNA序列比较提出全生命系统树，常考其三域（细菌、古菌、真核生物）划分；易错处是误认为全生命系统树是无根树，实际图中为有根树，根部代表地球上最先出现的生命。"], "code": null, "lang": null, "check": {"q": "Woese根据哪类分子序列比较首次提出涵盖整个生命界的系统树？", "o": ["A. 16S rRNA或18S rRNA", "B. 细胞色素b基因", "C. 线粒体DNA", "D. 叶绿体DNA"], "a": "A", "e": "Woese（1998；2000）根据某些代表生物16S rRNA或18S rRNA的序列比较，首次提出一个涵盖整个生命界的系统树。"}, "cards": [{"front": "全生命系统树的根代表什么？", "back": "根部的结代表地球上最先出现的生命，是现有生物的共同祖先。", "mnemonic": "根=共同祖先。", "useImg": false}]}, {"i": 5, "sec": "第一节 分子进化与系统发育", "title": "分子系统发育树构建方法概述与距离法", "notes": "本页进入第二节“分子系统发育树的构建方法”。利用统计方法重建系统发育树分别独立起始于形态学性状的数值分析法（Sneath and Sokal, 1973）和分析基因频率数据的群体遗传学（Cavalli-Sforza and Edwards, 1967）。分子进化的研究也出现在20世纪60年代，DNA技术革命使人们认识到DNA记录着进化的历史和信息。随着人类基因组计划实施，分子数据每年以指数方式增长，利用核苷酸和氨基酸序列数据重建系统发育树越来越受重视。分子系统发育分析根据生物大分子序列差异评估物种或分子间的进化，尤其强调生物大分子，与传统的形态学和基因频率数据有明显不同。利用生物大分子数据重建系统进化树，目前最常用的有4种方法：距离法、最大简约法、最大似然法和贝叶斯法。其中，最大简约法主要适用于序列相似性很高的情况；距离法在序列具有比较高相似性时适用；最大似然法和贝叶斯法可用于任何相关的数据序列集合。从计算速度来看，距离法最快，其次是最大简约法和贝叶斯法，然后是最大似然法。基于距离的系统发育树构建方法的基本思路是：首先获取分类群间进化距离的度量，然后依据距离度量重建一棵系统发育树，并使得该树能最好地反映已知序列之间的距离。这类方法有非加权分组平均法（UPGMA）、Fitch-Margoliash法（FMD）、最小进化法（ME）、最小二乘法（LS）和邻接法（NJ）等。本页开始介绍非加权分组平均法和最小二乘法等。", "page": 232, "level": "掌握", "img": "assets/img/ch11/p232.jpg", "anim": null, "fig": null, "points": ["重建系统发育树的统计方法独立起始于形态学性状数值分析法和群体遗传学基因频率分析。", "分子进化研究出现在20世纪60年代，DNA技术革命使人们认识到DNA记录着进化历史和信息。", "随着人类基因组计划等推进，分子系统发育树构建方法不断发展。", "距离法是一类基于距离矩阵构建系统发育树的方法。", "⚠️ 考点/易错点：分子系统发育树构建方法的两大独立起源常考：形态学性状数值分析法（Sneath and Sokal, 1973）和群体遗传学基因频率分析（Cavalli-Sforza and Edwards, 1967）；距离法基于序列差异数值构建系统树。"], "code": null, "lang": null, "check": {"q": "利用统计方法重建系统发育树分别独立起始于形态学性状的数值分析法和哪项研究？", "o": ["A. 分析基因频率数据的群体遗传学", "B. 蛋白质晶体学", "C. 基因组测序", "D. 代谢组学"], "a": "A", "e": "利用统计方法重建系统发育树分别独立起始于形态学性状的数值分析法（Sneath and Sokal, 1973）和分析基因频率数据的群体遗传学（Cavalli-Sforza and Edwards, 1967）。"}, "cards": [{"front": "重建系统发育树的统计方法独立起始于哪两个领域？", "back": "形态学性状的数值分析法和分析基因频率数据的群体遗传学。", "mnemonic": "形态数值+群体遗传。", "useImg": false}]}, {"i": 6, "sec": "第二节 分子系统发育树的构建方法", "title": "UPGMA 聚类过程与距离矩阵更新", "notes": "本页以距离矩阵为基础，讲解 UPGMA（非加权组平均法）逐步聚类构建系统发育树的过程。核心思想是：每次在距离矩阵中选择距离最小的一对序列或集合进行合并，形成新的节点，并计算分支点高度。若序列1和2距离最小，则先合并为集合(1-2)，分支点高度为 d12/2；新集合与其余序列 k 的距离按算术平均更新，例如 d(1-2),k=(d1k+d2k)/2。随后若集合(1-2)与序列3距离最小，则合并为(1-2-3)，分支点高度为(d12+d13+d23)/(3×2)，新集合与 k 的距离为三项平均。依次类推，直到所有序列合并。若最小距离不是 d12 而是 d45，则先合并4和5，再继续更新矩阵。该页强调 UPGMA 假设各分支进化速率近似相等，因此分支点高度可代表分化时间，树为超度量树。", "page": 233, "level": "掌握", "img": "assets/img/ch11/p233.jpg", "anim": null, "fig": null, "points": ["UPGMA（非加权组平均法）每次选择距离最小的一对序列或集合合并。", "合并后形成新节点，分支点高度为d12/2。", "新集合与其余序列k的距离按算术平均更新：d(1-2),k=(d1k+d2k)/2。", "重复聚类直至所有序列合并为一棵树。", "⚠️ 考点/易错点：UPGMA核心是每次合并距离最小的一对序列或集合，分支点高度为合并距离的一半；新集合与其余序列距离按算术平均更新，如d(1-2),k=(d1k+d2k)/2，易错处是忘记更新距离矩阵或误用其他平均方式。"], "code": null, "lang": null, "check": {"q": "在UPGMA中，若序列1和2距离最小，则分支点高度为？", "o": ["A. d12", "B. d12/2", "C. 2d12", "D. d12/4"], "a": "B", "e": "UPGMA每次选择距离最小的一对序列或集合合并，若序列1和2距离最小，则先合并为集合(1-2)，分支点高度为d12/2。"}, "cards": [{"front": "UPGMA每次选择哪一对序列或集合进行合并？新集合与其余序列的距离如何更新？", "back": "选择距离最小的一对；新距离按算术平均更新，如d(1-2),k=(d1k+d2k)/2。", "mnemonic": "最小距离合并，算术平均更新。", "useImg": false}]}, {"i": 7, "sec": "第二节 分子系统发育树的构建方法", "title": "UPGMA 实例与最小二乘法思想", "notes": "本页先用一个四分类单元实例完成 UPGMA：A、B 距离最小，合并为 AB，分支点高度 b=dAB/2=0.5；AB 与 C、D 的距离分别更新为(2+3)/2=2.5 和(4+3)/2=3.5。随后 C 与 D 距离最小，合并为 CD，分支点高度为 dCD/2=1；AB 与 CD 距离为(2.5+3.5)/2=3，最终合并，分支点高度为3/2=1.5，得到图11-3 的系统发育树。接着引入最小二乘法（least square, LS）：当进化谱系间核苷酸替代速率不同，UPGMA 可能给出错误拓扑，LS 允许不同分支速率不同。LS 将成对距离矩阵作为数据，通过使观察距离 dij 与树预测距离 eij 的残差平方和最小来估计枝长，预测距离是沿连接两物种通路上各枝长之和。残差平方和越小，树与距离拟合越好，可作为树的分值。", "page": 234, "level": "掌握", "img": "assets/img/ch11/p234.jpg", "anim": null, "fig": null, "points": ["四分类单元UPGMA实例：A、B距离最小，合并为AB，分支点高度b=dAB/2=0.5。", "AB与C、D的距离分别更新为(2+3)/2=2.5和(4+3)/2=3.5。", "C与D距离最小，合并为CD，分支点高度为dCD/2=1。", "AB与CD距离为(2.5+3.5)/2=3，最终合并，分支点高度为3/2=1.5。", "最小二乘法思想：最小化残差平方和R=ΣΣ(dij-eij)^2，使拟合最优的拓扑结构为最终树。", "⚠️ 考点/易错点：UPGMA实例中分支点高度计算易错：AB分支点高度b=dAB/2=0.5，CD分支点高度为dCD/2=1，最终合并高度为3/2=1.5；最小二乘法（LS）思想是使观测距离与树距离之差的平方和最小。"], "code": null, "lang": null, "check": {"q": "在UPGMA四分类单元实例中，A、B距离最小，dAB=1，则AB分支点高度为？", "o": ["A. 0.25", "B. 0.5", "C. 1", "D. 2"], "a": "B", "e": "实例中A、B距离最小，合并为AB，分支点高度b=dAB/2=0.5。"}, "cards": [{"front": "UPGMA实例中，A、B合并后分支点高度是多少？最终合并时分支点高度是多少？", "back": "A、B合并分支点高度b=dAB/2=0.5；最终合并分支点高度为3/2=1.5。", "mnemonic": "0.5，1.5。", "useImg": false}]}, {"i": 8, "sec": "第二节 分子系统发育树的构建方法", "title": "加权最小二乘法与 LS 实例", "notes": "本页继续最小二乘法。一般最小二乘法最小化残差平方和 R=ΣΣ(dij-eij)^2，使拟合最优的拓扑结构为最终树。Fitch 和 Margoliash 提出加权最小二乘法，R=ΣΣ wij(dij-eij)^2，其中权重 wij=1/dij^2，使距离较小、较可靠的成对比较影响更大。实例引用 Brown 等线粒体 DNA 数据，在 K80 模型下计算遗传距离，并用 LS 得到树 L[(人,黑猩猩),大猩猩,猩猩]及枝长 t1~t5。图中人与黑猩猩预测距离为 t1+t2，人与大猩猩为 t1+t5+t4 等，残差平方和是各观察距离与预测距离差平方之和。通过最小化 Rs，得到枝长估计，如 t1=0.008840、t2=0.043266、t3=0.053280、t4=0.058908、t5=0.135795，Rs=0.0003547。该页说明 LS 可用于估计枝长并比较拓扑。", "page": 235, "level": "掌握", "img": "assets/img/ch11/p235.jpg", "anim": null, "fig": null, "points": ["一般最小二乘法最小化残差平方和R=ΣΣ(dij-eij)^2。", "Fitch和Margoliash提出加权最小二乘法，R=ΣΣ wij(dij-eij)^2，权重wij=1/dij^2。", "加权使距离较小、较可靠的成对比较影响更大。", "实例引用Brown等线粒体DNA数据，在K80模型下计算遗传距离。", "⚠️ 考点/易错点：加权最小二乘法中权重 wij=1/dij^2，使距离较小（较可靠）的成对比较影响更大；易与普通最小二乘法 R=ΣΣ(dij-eij)^2 混淆。"], "code": null, "lang": null, "check": {"q": "Fitch和Margoliash提出的加权最小二乘法中，权重wij通常取为？", "o": ["A. 1/dij", "B. 1/dij^2", "C. dij", "D. dij^2"], "a": "B", "e": "加权最小二乘法中R=ΣΣ wij(dij-eij)^2，其中权重wij=1/dij^2，使距离较小、较可靠的成对比较影响更大。"}, "cards": [{"front": "加权最小二乘法的权重wij如何设置？", "back": "wij=1/dij^2，使距离较小、较可靠的成对比较影响更大。", "mnemonic": "权重反比距离平方。", "useImg": false}]}, {"i": 9, "sec": "第二节 分子系统发育树的构建方法", "title": "邻接法原理与算法步骤", "notes": "本页介绍邻接法（neighbor-joining, NJ）。NJ 基于最小进化原则，寻找使整棵树分支长度总和最小的一对节点进行归并。设 dij 为节点 i 和 j 间距离，先计算每个终端节点的净分歧度 ri=Σk dik。再计算速率校正距离 Mij=dij-(ri+rj)/(N-2)，选择 Mij 最小的一对节点 i、j 归并。新节点 u 与 i、j 的距离为 diu=dij/2+(ri-rj)/(2(N-2))，dju=dij-diu；新节点 u 与其余节点 k 的距离为 duk=(dik+djk-dij)/2。每归并一次，节点数 N 减1；若剩余终端节点多于2个，返回步骤1继续，直到树完全构建。NJ 不要求分子钟，能处理不同分支速率，是常用距离法。页末给出4条序列 A:TAGG、B:TACG、C:AAGC、D:AGCC 的实例起点，先两两比对计算遗传距离，再构建星状树并计算总枝长。", "page": 236, "level": "掌握", "img": "assets/img/ch11/p236.jpg", "anim": null, "fig": null, "points": ["邻接法（NJ）基于最小进化原则，寻找使整棵树分支长度总和最小的一对节点归并。", "计算每个终端节点的净分歧度ri=Σk dik。", "计算速率校正距离Mij=dij-(ri+rj)/(N-2)，选择Mij最小的一对节点i、j归并。", "新节点u与i、j的距离按公式计算，并更新距离矩阵。", "⚠️ 考点/易错点：NJ 法选择归并对象时用的是速率校正距离 Mij=dij-(ri+rj)/(N-2)，而非原始距离 dij；Mij 最小的一对才归并。"], "code": null, "lang": null, "check": {"q": "邻接法（NJ）中，速率校正距离Mij的计算公式为？", "o": ["A. Mij=dij+(ri+rj)/(N-2)", "B. Mij=dij-(ri+rj)/(N-2)", "C. Mij=dij-(ri-rj)/(N-2)", "D. Mij=dij+(ri-rj)/(N-2)"], "a": "B", "e": "NJ先计算每个终端节点的净分歧度ri=Σk dik，再计算速率校正距离Mij=dij-(ri+rj)/(N-2)，选择Mij最小的一对节点归并。"}, "cards": [{"front": "邻接法（NJ）中速率校正距离Mij的计算公式是什么？", "back": "Mij=dij-(ri+rj)/(N-2)，其中ri=Σk dik。", "mnemonic": "M=d-(ri+rj)/(N-2)。", "useImg": false}]}, {"i": 10, "sec": "第二节 分子系统发育树的构建方法", "title": "邻接法实例：选择邻居与枝长计算", "notes": "本页继续 NJ 实例。对 A、B、C、D 四序列，先构建星状树，利用两两距离求总枝长。通过比较不同邻居组合的总枝长 Sij，发现 A 与 B 为邻居或 C 与 D 为邻居时总枝长最短，最终结果相同。以 A、B 为邻居时，枝长 a=[dAB+(dAC+dBC)/2-(dCD+dBD)/2]/2=0.5，b=[dAB+(dAC+dBC)/2-(dCD+dAD)/2]/2=0.5。将 A、B 合并为集合 H，更新 H 与 C、D 的距离，例如 dHC=(dAC+dBC-dAB)/2 等，得到新的距离矩阵。重复选择邻居、计算枝长、合并集合，直到全部序列合并。随后对剩余 H、C、D 三个序列构建星状树，总枝长公式为(dHC+dHD+dCD)/2，并继续选择 H 与 C 作为邻居，为下一页最终树做准备。", "page": 237, "level": "掌握", "img": "assets/img/ch11/p237.jpg", "anim": null, "fig": null, "points": ["NJ实例：对A、B、C、D四序列，先构建星状树，利用两两距离求总枝长。", "比较不同邻居组合的总枝长Sij，发现A与B为邻居或C与D为邻居时总枝长最短，最终结果相同。", "以A、B为邻居时，枝长a=[dAB+(dAC+dBC)/2-(dCD+dBD)/2]/2=0.5。", "枝长b=[dAB+(dAC+dBC)/2-(dCD+dAD)/2]/2=0.5。", "⚠️ 考点/易错点：NJ 中不同邻居组合（A-B 或 C-D）可能给出相同总枝长，最终拓扑一致；枝长公式 a=[dAB+(dAC+dBC)/2-(dCD+dBD)/2]/2 易记错。"], "code": null, "lang": null, "check": {"q": "在NJ实例中，以A、B为邻居时，枝长a的计算结果为？", "o": ["A. 0.5", "B. 1.0", "C. 1.5", "D. 2.0"], "a": "A", "e": "以A、B为邻居时，枝长a=[dAB+(dAC+dBC)/2-(dCD+dBD)/2]/2=0.5，b=0.5。"}, "cards": [{"front": "NJ实例中，以A、B为邻居时，枝长a和b分别是多少？", "back": "a=0.5，b=0.5。", "mnemonic": "a=b=0.5。", "useImg": false}]}, {"i": 11, "sec": "第二节 分子系统发育树的构建方法", "title": "NJ 最终树与最大简约法概念", "notes": "本页完成 NJ 实例：当 H 与 C 为邻居时，枝长 h=(dHC+dHD-dCD)/2=(2+3-2)/2=1.5，c=(dHC+dCD-dHD)/2=(2+2-3)/2=0.5；将 H、C 合并为 J，J 与 D 的距离 dJD=(dHD+dCD-dHC)/2=(3+2-2)/2=1.5。最终画出图11-10 的系统发育树，A、C 各以0.5枝长连到内部节点，B 以0.5连到 A 所在分支，D 以1.5连到根部附近。随后引入最大简约法（maximum parsimony, MP）：根据离散性状（如 DNA、蛋白质序列变异）构建系统发育树，遵循简约性原则，所需变异次数最少、演化步数最少的树最可能符合自然情况。MP 分为非加权（同等加权）和加权分析，加权可依据性状演化规律如不同位点进化速率不同。只有至少在两个以上分类单元中存在差异的性状或位点才能提供有效信息，DNA 中这类位点称为简约性信息位点。", "page": 238, "level": "掌握", "img": "assets/img/ch11/p238.jpg", "anim": null, "fig": "图11-10为NJ最终树，分支长度标注在分支上，节点代表祖先，末端代表现存序列。", "points": ["NJ实例完成：当H与C为邻居时，枝长h=(dHC+dHD-dCD)/2=(2+3-2)/2=1.5。", "枝长c=(dHC+dCD-dHD)/2=(2+2-3)/2=0.5。", "将H、C合并为J，J与D的距离dJD=(dHD+dCD-dHC)/2=(3+2-2)/2=1.5。", "最终画出图11-10的系统发育树，A、C各以0.5枝长连到内部节点。", "最大简约法（MP）基于奥卡姆剃刀原则，认为解释性状变化所需替换数最少的系统发育树最优。", "⚠️ 考点/易错点：合并后需更新新节点与其余节点的距离，如 dJD=(dHD+dCD-dHC)/2；注意 NJ 是无根树，最终枝长分配易算错。"], "code": null, "lang": null, "check": {"q": "在NJ实例最终树中，D连接到根部附近的枝长为？", "o": ["A. 0.5", "B. 1.0", "C. 1.5", "D. 2.0"], "a": "C", "e": "最终画出系统发育树，A、C各以0.5枝长连到内部节点，B以0.5连到A所在分支，D以1.5连到根部附近。"}, "cards": [{"front": "NJ实例中，当H与C为邻居时，枝长h和c分别是多少？", "back": "h=1.5，c=0.5。", "mnemonic": "h=1.5，c=0.5。", "useImg": false}]}, {"i": 12, "sec": "第二节 分子系统发育树的构建方法", "title": "最大简约法的基本思想与搜索策略", "notes": "本页介绍最大简约法（maximum parsimony, MP）的基本原理。MP 基于奥卡姆剃刀原则，认为解释性状变化所需替换数最少的系统发育树最优。其基本思想是：对给定分类单元的所有可能树，推断每个位点祖先序列的核苷酸（或氨基酸），统计每个位点阐明差异所需的最小替换数目；整棵树所有简约信息位点的最小替换数总和称为树的长度或代价。比较所有可能树，选择长度最小、代价最小的树作为最大简约树（maximum parsimony tree）。MP 能推断祖先序列，填补分子进化研究空白，从现存后代序列客观推断中间状态。构建步骤：①序列比对；②写出所有可能的树；③分析信息位点；④将每棵树的信息位点字符替换数相加，寻找最小替换的树。当物种数 n<10 时，可直接计算所有可能树的长度，称为穷举式搜索；但树的数量随 n 增加急剧增长。MP 适用于相近物种间演化关系分析，因趋同演化可能使不同进化过程的生物被归为一支。", "page": 239, "level": "掌握", "img": "assets/img/ch11/p239.jpg", "anim": null, "fig": null, "points": ["MP基本思想：对给定分类单元的所有可能树，推断每个位点祖先序列的核苷酸（或氨基酸）。", "统计每个位点阐明差异所需的最小替换数目。", "整棵树所有简约信息位点的最小替换数总和称为树的长度或代价。", "比较所有可能树，选择长度最小的树作为最优树。", "⚠️ 考点/易错点：最大简约法基于奥卡姆剃刀，树的长度/代价是所有简约信息位点最小替换数之和，选代价最小的树；非信息位点不计入。"], "code": null, "lang": null, "check": {"q": "最大简约法（MP）基于什么原则？", "o": ["A. 奥卡姆剃刀原则", "B. 最大似然原则", "C. 贝叶斯后验概率原则", "D. 最小二乘原则"], "a": "A", "e": "MP基于奥卡姆剃刀原则，认为解释性状变化所需替换数最少的系统发育树最优。"}, "cards": [{"front": "最大简约法（MP）的基本思想是什么？", "back": "基于奥卡姆剃刀原则，认为解释性状变化所需替换数最少的系统发育树最优。", "mnemonic": "最少替换，奥卡姆剃刀。", "useImg": false}]}, {"i": 13, "sec": "第二节 分子系统发育树的构建方法", "title": "最大简约法实例与最大似然法引入", "notes": "本页通过实例演示最大简约法。给定 4 条序列：d1: TAGG; d2: TACG; d3: AAGC; d4: AGCC。4 个类群有 3 种可能的无根树（图 11-11）。4 个位点均为信息位点。分析第一位点碱基替换：树 A、B、C 的替换数依次为 1、2、2；第二位点均为 1；第三位点为 2、1、1；第四位点为 1、2、2。汇总得树 A、B、C 的替换数分别为 5、6、6。树 A 替换数最少，为最大简约树。此外，本页还介绍了最大似然法（maximum likelihood, ML）的开头：ML 完全基于统计方法，计算量最大。以一个特定替代模型分析序列数据，使每个拓扑结构的似然率最大，选择最大似然值最大的拓扑结构为最终树。所考虑的参数是每个拓扑结构的枝长，并对似然值求最大来估计枝长。单个位点的似然值是该位点每个可能被取代或再现的概率之和，进化树的似然值就是所有位点似然值的乘积。ML 核心是在比对中充分考虑每个核苷酸的概率，例如转换概率约为颠换的 3 倍。", "page": 240, "level": "掌握", "img": "assets/img/ch11/p240.jpg", "anim": null, "fig": "图11-11为3种可能的无根树拓扑结构，通过比较各位点替换数确定最优树。", "points": ["MP实例：4条序列d1:TAGG; d2:TACG; d3:AAGC; d4:AGCC。", "4个类群有3种可能的无根树（图11-11），4个位点均为信息位点。", "分析第一位点碱基替换：树A、B、C的替换数依次为1、2、2。", "第二位点均为1；第三位点为2、1、1；第四位点为1、2、2。", "汇总得树A、B、C的替换数，选择替换数最小的树为最优树。", "⚠️ 考点/易错点：4 类群有 3 种无根树，需逐位点统计替换数并汇总；树 A 替换数 5 最少为最大简约树，易漏算或错算某位点。"], "code": null, "lang": null, "check": {"q": "在最大简约法实例中，4条序列d1:TAGG、d2:TACG、d3:AAGC、d4:AGCC，树A、B、C的替换数分别为？", "o": ["A. 5、6、6", "B. 6、5、6", "C. 6、6、5", "D. 5、5、6"], "a": "A", "e": "汇总得树A、B、C的替换数分别为5、6、6。树A替换数最少，为最大简约树。"}, "cards": [{"front": "MP实例中，4条序列d1:TAGG; d2:TACG; d3:AAGC; d4:AGCC，共有几种可能的无根树？", "back": "3种。", "mnemonic": "4类群3种无根树。", "useImg": false}]}, {"i": 14, "sec": "第二节 分子系统发育树的构建方法", "title": "最大似然法的算法与似然值计算", "notes": "本页详细讲解最大似然法（ML）的算法。以一个特定的替代模型分析既定序列数据，使每个拓扑结构的似然值最大，筛选最大似然值的拓扑结构为最终树。计算给定 DNA 序列树的似然值：考虑一个简单 4 类群树，假定 DNA 序列为 n 个核苷酸长度，无插入或缺失（图 11-13）。假设进化从内部节点 d5 开始，似然函数 L 为：L = f5 * P_{d5,d1}(v1) * P_{d5,d2}(v2) * P_{d5,d6}(v5) * P_{d6,d3}(v3) * P_{d6,d4}(v4)，其中 f5 为某个字符的概率，P_{d5,d1}(v1) 为从节点 d5 的字符替换到节点 d1 的字符的概率，依此类推。概率 P_{ij}(v) 可用下式表示：P_{ij}(v) = f_j * (1 - e^{-...}) 等（具体公式依替代模型而定）。ML 法计算量最大，但能充分利用每个核苷酸的概率信息，适用于任何相关数据序列集合。", "page": 241, "level": "理解", "img": "assets/img/ch11/p241.jpg", "anim": null, "fig": "图11-13为4类群树示意图，内部节点d5、d6，分支长度v1-v5，用于计算似然值。", "points": ["最大似然法（ML）以一个特定的替代模型分析既定序列数据。", "使每个拓扑结构的似然值最大，筛选最大似然值的拓扑结构为最终树。", "计算给定DNA序列树的似然值：考虑一个简单4类群树，假定DNA序列为n个核苷酸长度，无插入或缺失。", "假设进化从内部节点d5开始，似然函数L为：L = f5 * P_{d5,d1}(v...)。", "⚠️ 考点/易错点：ML 法对每个拓扑结构计算似然值，取最大者；似然函数需对内部节点所有可能字符求和，枝长与替代模型参数影响结果。"], "code": null, "lang": null, "check": {"q": "最大似然法（ML）中，最终选择的拓扑结构是？", "o": ["A. 似然值最小的拓扑结构", "B. 似然值最大的拓扑结构", "C. 分支长度总和最小的拓扑结构", "D. 替换数最少的拓扑结构"], "a": "B", "e": "ML以一个特定的替代模型分析既定序列数据，使每个拓扑结构的似然值最大，筛选最大似然值的拓扑结构为最终树。"}, "cards": [{"front": "最大似然法（ML）中，似然函数L如何表示？", "back": "L = f5 * P_{d5,d1}(v...)，考虑内部节点d5和d6的所有可能字符。", "mnemonic": "似然函数=频率×转移概率。", "useImg": false}]}, {"i": 15, "sec": "第二节 分子系统发育树的构建方法", "title": "最大似然法实例与贝叶斯推断法引入", "notes": "本页通过实例计算最大似然树。假设树 A 的两个内部节点为 d5 与 d6，进化从 d5 开始，任意位点 X 的似然函数为 16 项之和（节点 5 和 6 各有 4 种可能字符）。给定枝长 0.1，计算得第一位点似然值 L1sum = 8.71×10^-5，第二位点 L2sum = 8.71×10^-5，第三位点 L3sum = 6.67×10^-4。树 A 的对数似然函数值 lnLA = ln(L1sum * L2sum * L3sum) = -19.10。同理树 B 和树 C 的对数似然值为 lnLB = -21.12，lnLC = -24.55。树 A 对数似然值最大，为所求最大似然进化树。实际中枝长通过最大似然法估计，计算更复杂。本页还引入贝叶斯推断法（Bayesian inference, BI），是最近几年发展起来的一种构树方法，基于贝叶斯推理和马尔可夫模型，详见第十二章第四、五节。", "page": 242, "level": "理解", "img": "assets/img/ch11/p242.jpg", "anim": null, "fig": null, "points": ["ML实例：假设树A的两个内部节点为d5与d6，进化从d5开始。", "任意位点X的似然函数为16项之和（节点5和6各有4种可能字符）。", "给定枝长0.1，计算得第一位点似然值L1sum=8.71×10^-5，第二位点L2sum=8.71×10^-5，第三位点L3sum=6.67×10^-4。", "树A的似然值最大，为最优树。", "贝叶斯推断法引入：基于后验概率选择最优树。", "⚠️ 考点/易错点：多位点总似然为各位点似然之积，对数似然为各位点对数似然之和；易误将似然值直接相加而非相乘。"], "code": null, "lang": null, "check": {"q": "在最大似然法实例中，树A的对数似然函数值lnLA由哪些位点似然值相乘后取对数得到？", "o": ["A. L1sum、L2sum、L3sum", "B. L1sum、L2sum", "C. L2sum、L3sum", "D. 仅L1sum"], "a": "A", "e": "树A的对数似然函数值lnLA=ln(L1sum * L2sum * L3sum)，其中L1sum=8.71×10^-5，L2sum=8.71×10^-5，L3sum=6.67×10^-4。"}, "cards": [{"front": "ML实例中，树A的第一位点似然值L1sum是多少？", "back": "L1sum = 8.71×10^-5。", "mnemonic": "8.71e-5。", "useImg": false}]}, {"i": 16, "sec": "第二节 分子系统发育树的构建方法", "title": "系统发育树构建步骤与分子序列选择", "notes": "本页进入第三节“系统发育树构建及应用”。构建系统发育树一般分 4 步：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。选择分子序列：生物体不同株系后代的 DNA 在进化中累积突变，导致大分子序列产生分歧，分子系统发育分析利用这些同源序列构建系统发育树。可用 DNA、RNA 或蛋白质序列。通常 DNA 序列信息量比蛋白质多，更精确，原因：1）编码区可发生同义或非同义替换，DNA 序列能获取两者信息；2）比较非同义替换率（dN）和同义替换率（dS）可显示正选择或纯化选择，纯化选择 dN<dS，正选择 dN>dS；3）非编码区受较小选择压力，发生更多中性突变，可用于建树；4）DNA 序列可估计转换和颠换速率。因此，当一个基因改变非常慢时，或需要更多信息时，优先选择 DNA 序列。", "page": 243, "level": "掌握", "img": "assets/img/ch11/p243.jpg", "anim": null, "fig": null, "points": ["构建系统发育树一般分4步：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。", "选择分子序列：利用同源序列构建系统发育树，可用DNA、RNA或蛋白质序列。", "通常DNA序列信息量比蛋白质多，更精确。", "生物体不同株系后代的DNA在进化中累积突变，导致大分子序列产生分歧。", "⚠️ 考点/易错点：构建系统发育树4步骤的顺序（选序列→多序列比对→选建树方法→树评估）易考；DNA比蛋白质信息量大的原因（编码区同义/非同义替换均可获取）易混。"], "code": null, "lang": null, "check": {"q": "构建系统发育树一般分为4步，下列哪项不属于这4步？", "o": ["A. 选择适合的分子序列", "B. 多序列比对", "C. 选择适合的建树方法", "D. 测定蛋白质三维结构"], "a": "D", "e": "构建系统发育树一般分4步：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。"}, "cards": [{"front": "构建系统发育树一般分哪4步？", "back": "①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。", "mnemonic": "选序列，比对，建树，评估。", "useImg": false}]}, {"i": 17, "sec": "第二节 分子系统发育树的构建方法", "title": "多序列比对与建树方法选择", "notes": "本页继续讲解系统发育树构建步骤。多序列比对：根据二级或三级序列结构进行比对比直接利用一级序列更可信，因为复杂结构的保守性高于简单特征的同源保守性；复杂结构比对程序还可搜索特殊关联位点（进化功能区）。例如核糖体基因二级结构通常为茎环（stem-loop）结构，茎区保守，环区高度可变。若类群中有相应二级结构，应根据二级结构比对。当序列分歧度大或有大的插入/缺失（indel）片段时，处理 indel 状态位点取决于进化模型要素（包括核苷酸转换/颠换速率），且相关参数在前导树与比对推导的进化树中应保持一致。比对参数应随进化分支动态变化，降低碱基错配概率，同时防止过多近似序列导致信息量不足。选择建树方法：最大简约法主要适用于序列相似性很高的情况；距离法在序列相似性较高时适用；最大似然法和贝叶斯法可用于任何相关数据序列集合。计算速度：距离法最快，其次最大简约法和贝叶斯方法，最大似然法最慢。实际应用中需兼顾计算速度、分子数据特点和方法适用范围。距离法是纯数学算法，通过序列两两差异决定拓扑结构和枝长，将建树和最优树确定融合，但转换距离矩阵时会丢失部分进化信息。最大简约法和最大似然法从数学角度评价树的最优标准，寻找使目标函数最优的树。", "page": 244, "level": "掌握", "img": "assets/img/ch11/p244.jpg", "anim": null, "fig": null, "points": ["多序列比对：根据二级或三级序列结构进行比对比直接利用一级序列更可信。", "复杂结构的保守性高于简单特征的同源保守性。", "复杂结构比对程序还可搜索特殊关联位点（进化功能区）。", "例如核糖体基因二级结构通常为茎环结构，茎区保守，环区高度可变。", "当序列分歧度大或有大的插入/缺失时，应结合二级结构进行比对。", "⚠️ 考点/易错点：易错点：多序列比对应优先依据二级/三级结构而非一级序列，因复杂结构保守性更高；茎环结构中茎区保守、环区可变，处理indel位点取决于进化模型。"], "code": null, "lang": null, "check": {"q": "关于多序列比对，下列说法正确的是？", "o": ["A. 直接利用一级序列比对比根据二级或三级结构比对更可信", "B. 根据二级或三级序列结构进行比对比直接利用一级序列更可信", "C. 二级结构比对不适用于核糖体基因", "D. 环区比茎区更保守"], "a": "B", "e": "根据二级或三级序列结构进行比对比直接利用一级序列更可信，因为复杂结构的保守性高于简单特征的同源保守性。核糖体基因二级结构通常为茎环结构，茎区保守，环区高度可变。"}, "cards": [{"front": "为什么根据二级或三级序列结构进行多序列比对更可信？", "back": "因为复杂结构的保守性高于简单特征的同源保守性。", "mnemonic": "结构保守性更高。", "useImg": false}]}, {"i": 18, "sec": "第三节 系统发育树构建及应用", "title": "系统发育树可靠性的重复抽样检验：自展法与折刀法", "notes": "本页介绍系统发育树构建后的可靠性评估。由于距离法、最大简约法或最大似然法得到的树只是一个点估计，需要加上可靠性测度。常用重复抽样检验排除随机误差影响，主要包括自展检验（bootstrap）和折刀法（jackknife）。自展检验利用计算机从原始数据集中随机重采样产生伪数据集，称为自展样本；对每个自展样本用相同建树方法构建自展树；重复成百上千次后，统计最终树中各个分支在自展树中出现的频率，即自展支持率。支持率越高，表示该分支越可靠。若不同位点具有一致的系统发育信号，则多数分支支持率高；若数据缺乏信息或位点间信号冲突，则支持率低。折刀法与自展法区别在于抽样方式，由Muller和Ayala提出。学习时应掌握自展支持率的概念、计算流程及解读，理解其作为分支置信度指标的意义。", "page": 245, "level": "掌握", "img": "assets/img/ch11/p245.jpg", "anim": null, "fig": null, "points": ["系统发育树构建后需进行可靠性评估，常用重复抽样检验。", "自展检验（bootstrap）：从原始数据集中随机重采样产生伪数据集，构建自展树，重复成百上千次。", "统计最终树中分支出现的频率，作为该分支的置信度。", "折刀法（jackknife）：类似自展，但每次删除部分数据。", "重复抽样检验可排除随机误差影响。", "⚠️ 考点/易错点：自展法（bootstrap）与折刀法（jackknife）的区别及自展支持率的含义是核心考点：支持率越高分支越可靠，注意其评估的是分支可靠性而非树本身正确性。"], "code": null, "lang": null, "check": {"q": "系统发育树可靠性评估中，自展检验的英文是？", "o": ["A. bootstrap", "B. jackknife", "C. likelihood", "D. parsimony"], "a": "A", "e": "常用重复抽样检验主要包括自展检验（bootstrap）和折刀法（jackknife）。自展检验利用计算机从原始数据集中随机重采样产生伪数据集。"}, "cards": [{"front": "自展检验（bootstrap）的基本步骤是什么？", "back": "从原始数据集中随机重采样产生伪数据集，构建自展树，重复成百上千次，统计分支出现频率作为置信度。", "mnemonic": "重采样，建树，统计频率。", "useImg": false}]}, {"i": 19, "sec": "第三节 系统发育树构建及应用", "title": "PHYLIP系统发育分析软件包简介", "notes": "本页首先指出最大简约法和最大似然法构建的树中所有内部分支均为正值，难以建立检验无效假设的分析方法。随后介绍常用系统发育树软件PHYLIP。PHYLIP由美国华盛顿大学Joseph Felsenstein教授开发，1980年首次发布，可在DOS、UNIX、Windows和Macintosh等平台运行，是免费软件包。它由35个独立程序组成，覆盖系统发育分析各方面，主要包括：分子序列组（蛋白质序列程序如protpars、proml、promlk、protdist；核苷酸序列程序如dnapars、dnaml、dnadist等）、距离矩阵组（fitch、kitsch、neighbor）、基因频率组（gendist、contrast、contml）、离散字符组（pars、mix、penny、dollop等）和进化树绘制组（drawgram、drawtree、consense、treedist、retree）。每个程序有独立文档。学习时应了解PHYLIP的功能模块和常用程序，理解其在系统发育分析中的地位。", "page": 246, "level": "理解", "img": "assets/img/ch11/p246.jpg", "anim": null, "fig": null, "points": ["最大简约法和最大似然法构建的树中所有内部分支均为正值，难以建立检验无效假设的分析方法。", "PHYLIP由美国华盛顿大学Joseph Felsenstein教授开发，1980年首次发布。", "PHYLIP可在DOS、UNIX、Windows和Macintosh等平台运行，是免费软件包。", "PHYLIP由35个独立程序组成，覆盖系统发育分析各方面。", "⚠️ 考点/易错点：易考PHYLIP的开发者（Joseph Felsenstein）、发布年份（1980）、免费跨平台及由35个独立程序组成；注意最大简约法/最大似然法内部分支均为正值难以做无效假设检验这一前提。"], "code": null, "lang": null, "check": {"q": "PHYLIP软件包由哪位教授开发？", "o": ["A. Joseph Felsenstein", "B. Kumar", "C. Woese", "D. Kimura"], "a": "A", "e": "PHYLIP由美国华盛顿大学Joseph Felsenstein教授开发，1980年首次发布，由35个独立程序组成。"}, "cards": [{"front": "PHYLIP软件由谁开发？何时首次发布？", "back": "由美国华盛顿大学Joseph Felsenstein教授开发，1980年首次发布。", "mnemonic": "Felsenstein，1980。", "useImg": false}]}, {"i": 20, "sec": "第三节 系统发育树构建及应用", "title": "PAUP与MEGA软件简介", "notes": "本页继续介绍系统发育分析软件。PAUP可通过“estimate”和“describe tree”命令评估系统发育树参数，下载地址为http://paup.sc.fsu.edu/，另有可视化版本AWTY。重点介绍MEGA（Molecular Evolutionary Genetics Analysis），由美国亚利桑那州立大学Kumar教授编写，是免费分子进化遗传分析软件包。MEGA 4.0功能包括网络数据搜索、遗传距离估计、多序列比对、系统发育树构建和进化假说检验，支持DNA、mRNA、氨基酸序列及遗传距离建树。建树方法提供距离法（UPGMA、ME、NJ）和最大简约法，可进行自展检验及标准误估计。MEGA突出特点是菜单化操作，简单易掌握。MEGA5新增TBR和SPR用于种系发生重建；MEGA6新增Timetree功能，基于Reltime方法估计分歧时间；最新版本MEGA7.1.0于2017年8月发布，支持64位系统。学习时应了解MEGA的主要功能和版本演进。", "page": 247, "level": "理解", "img": "assets/img/ch11/p247.jpg", "anim": null, "fig": null, "points": ["PAUP可通过“estimate”和“describe tree”命令评估系统发育树参数，下载地址为http://paup.sc.fsu.edu/。", "PAUP另有可视化版本AWTY。", "MEGA（Molecular Evolutionary Genetics Analysis）由美国亚利桑那州立大学Kumar教授编写，是免费分子进化分析软件。", "MEGA集成了序列比对、距离计算、建树和树可视化等功能。", "⚠️ 考点/易错点：易混：PAUP与MEGA的开发者、功能定位不同；MEGA由Kumar编写、免费，功能涵盖遗传距离估计、多序列比对等，注意其版本（4.0）与下载地址等细节。"], "code": null, "lang": null, "check": {"q": "MEGA软件由哪所大学的Kumar教授编写？", "o": ["A. 美国亚利桑那州立大学", "B. 美国华盛顿大学", "C. 法国巴斯德研究所", "D. 英国剑桥大学"], "a": "A", "e": "MEGA（Molecular Evolutionary Genetics Analysis）由美国亚利桑那州立大学Kumar教授编写，是免费分子进化遗传分析软件包。"}, "cards": [{"front": "MEGA软件由谁编写？主要功能是什么？", "back": "由美国亚利桑那州立大学Kumar教授编写，是免费分子进化分析软件，集成了序列比对、距离计算、建树和树可视化等功能。", "mnemonic": "Kumar，MEGA，免费集成。", "useImg": false}]}, {"i": 21, "sec": "第三节 系统发育树构建及应用", "title": "系统发育分析示例：线粒体Cytb基因数据与MEGA建树流程", "notes": "本页开始系统发育分析示例。选用来自13种脊椎动物线粒体基因组中细胞色素b（Cytb）基因编码的氨基酸序列。线粒体DNA（mtDNA）包含13个编码蛋白质的基因，广泛应用于系统发育、种群遗传变异和近缘种鉴定。Cytb基因是结构和功能研究最清楚的基因之一，碱基组成有偏好性和种间差异，同时存在快慢进化密码子位点及保守和突变区域，适合系统分类研究。1989年第一对脊椎动物Cytb基因扩增引物出现后，该基因被广泛应用。本例选取哺乳动物、爬行动物、鸟类和鱼类共13个物种的Cytb氨基酸序列构建系统发育树。首先介绍利用MEGA 4构建树，包括序列获取：通过Entrez检索获取13个物种的氨基酸序列，登录号见表11-2。学习时应掌握Cytb基因作为分子标记的特点及序列获取方法。", "page": 248, "level": "掌握", "img": "assets/img/ch11/p248.jpg", "anim": null, "fig": null, "points": ["系统发育分析示例选用13种脊椎动物线粒体基因组中细胞色素b（Cytb）基因编码的氨基酸序列。", "线粒体DNA（mtDNA）包含13个编码蛋白质的基因，广泛应用于系统发育、种群遗传变异和近缘种鉴定。", "Cytb基因是结构和功能研究最清楚的基因之一，碱基组成有偏好性和种间差异。", "Cytb基因存在快慢进化密码子位点及保守和突变区域，适合系统分类研究。", "1989年第一对脊椎动物Cytb基因引物被设计。", "⚠️ 考点/易错点：易考Cytb基因作为分子标记的优点（结构功能清楚、碱基组成偏好、快慢进化位点并存、适合系统分类）及mtDNA含13个编码蛋白基因；注意1989年引物出现这一时间点。"], "code": null, "lang": null, "check": {"q": "系统发育分析示例中选用的分子数据是？", "o": ["A. 13种脊椎动物线粒体Cytb基因编码的氨基酸序列", "B. 人类基因组30亿碱基对序列", "C. 大肠杆菌16S rRNA序列", "D. 酵母全基因组序列"], "a": "A", "e": "示例选用来自13种脊椎动物线粒体基因组中细胞色素b（Cytb）基因编码的氨基酸序列。"}, "cards": [{"front": "系统发育分析示例选用了什么基因？为什么？", "back": "选用线粒体细胞色素b（Cytb）基因；因为它是结构和功能研究最清楚的基因之一，碱基组成有偏好性和种间差异，存在快慢进化密码子位点及保守和突变区域，适合系统分类研究。", "mnemonic": "Cytb，结构清楚，适合分类。", "useImg": false}]}, {"i": 22, "sec": "第三节 系统发育树构建及应用", "title": "MEGA中序列导入与ClustalW多序列比对参数设置", "notes": "本页展示MEGA 4操作步骤。打开MEGA软件，将cyth.fasta文件拖入软件，弹出“Alignment Explorer”模块对话框（图11-16），其中显示蛋白质序列。在Alignment Explorer中选择“Alignment”→“Align by ClustalW”命令，弹出“ClustalW Parameters”对话框（图11-17），用于设置多序列比对参数。多序列比对是系统发育分析的关键步骤，目的是使同源位点对齐，为后续建树提供可靠数据。ClustalW参数通常包括空位开放罚分、空位延伸罚分、替换矩阵等。学习时应理解多序列比对在系统发育分析中的必要性，掌握在MEGA中导入序列并调用ClustalW进行比对的基本操作。图示含义：图11-16为比对浏览器界面，图11-17为ClustalW参数设置窗口。", "page": 249, "level": "掌握", "img": "assets/img/ch11/p249.jpg", "anim": null, "fig": "图11-16为Alignment Explorer界面，显示蛋白质序列；图11-17为ClustalW Parameters对话框，设置比对参数。", "points": ["MEGA 4操作：打开软件，将cyth.fasta文件拖入，弹出“Alignment Explorer”模块对话框。", "在Alignment Explorer中选择“Alignment”→“Align by ClustalW”命令。", "弹出“ClustalW Parameters”对话框，设置比对参数。", "完成多序列比对后，可进行后续建树分析。", "⚠️ 考点/易错点：易错点：MEGA中需先将序列文件拖入并进入Alignment Explorer，再选Align by ClustalW设置参数；多序列比对目的是使同源位点对齐，是建树关键步骤。"], "code": null, "lang": null, "check": {"q": "在MEGA中，选择“Alignment”→“Align by ClustalW”命令后弹出的对话框是？", "o": ["A. ClustalW Parameters", "B. Analysis Preferences", "C. Alignment Explorer", "D. Tree Explorer"], "a": "A", "e": "在Alignment Explorer中选择“Alignment”→“Align by ClustalW”命令，弹出“ClustalW Parameters”对话框，用于设置多序列比对参数。"}, "cards": [{"front": "在MEGA中如何调用ClustalW进行多序列比对？", "back": "在Alignment Explorer中选择“Alignment”→“Align by ClustalW”命令，弹出ClustalW Parameters对话框设置参数。", "mnemonic": "Alignment菜单→Align by ClustalW。", "useImg": false}]}, {"i": 23, "sec": "第三节 系统发育树构建及应用", "title": "MEGA分析参数设置与系统发育树计算", "notes": "本页继续MEGA建树流程。在完成多序列比对后，点击“Compute”按钮开始计算。弹出“Analysis Preferences”对话框（图11-19），用于设置分析参数。图中显示：Data Type为Amino acid；Phylogeny Test and options选择Bootstrap，500次重复，随机种子31332；Gaps/Missing Data选择Complete Deletion；Substitution Model选择Amino: Poisson correction。这些参数决定建树方法和可靠性检验方式。计算所耗时间与序列数目及信息位点含量成正比。计算完成后弹出TreeExplorer窗口（图11-20），用于查看和编辑系统发育树。学习时应掌握MEGA中分析参数的含义：自展重复次数、缺失数据完全删除、氨基酸替换模型等，理解这些设置对建树结果的影响，并能解读TreeExplorer中的树图。", "page": 250, "level": "掌握", "img": "assets/img/ch11/p250.jpg", "anim": null, "fig": "图11-19为Analysis Preferences对话框，显示参数设置选项。", "points": ["完成多序列比对后，点击“Compute”按钮开始计算。", "弹出“Analysis Preferences”对话框，设置分析参数。", "Data Type为Amino acid；Phylogeny Test and options选择Bootstrap，500次重复，随机种子31332。", "Gaps/Missing Data Treatment等参数也需设置。", "设置完成后点击“Compute”进行系统发育树计算。", "⚠️ 考点/易错点：易考MEGA分析参数设置细节：Data Type为Amino acid、Bootstrap 500次重复、随机种子31332、Gaps/Missing Data选Complete Deletion，这些具体参数值易成为考点。"], "code": null, "lang": null, "check": {"q": "在MEGA的Analysis Preferences对话框中，Bootstrap重复次数设置为？", "o": ["A. 100次", "B. 500次", "C. 1000次", "D. 2000次"], "a": "B", "e": "图中显示Phylogeny Test and options选择Bootstrap，500次重复，随机种子31332。"}, "cards": [{"front": "MEGA分析参数设置中，Bootstrap重复次数和随机种子是多少？", "back": "Bootstrap 500次重复，随机种子31332。", "mnemonic": "500次，31332。", "useImg": false}]}, {"i": 24, "sec": "第三节 系统发育树构建及应用", "title": "在线系统发育分析平台Mobyle", "notes": "本页介绍利用互联网进行生物信息学在线分析的工具，重点介绍法国巴斯德研究所构建的Mobyle平台。Mobyle集成了多种在线分析软件，包括数据库搜索、序列格式转换与编辑、序列比对和比较、系统发育分析、蛋白质序列分析、核酸序列分析以及结构分析等模块。在系统发育分析模块中，平台提供了简约法程序、距离矩阵法程序、最大似然法程序、距离计算以及系统发育树的操作与可视化等在线分析工具。这些工具使得研究者无需在本地安装复杂软件，即可通过网页界面完成系统发育树的构建和分析。Mobyle的网址为http://mobyle.rpbs.univ-paris-diderot.fr/。该页还提及PHYML等程序可通过在线分析构建系统发育树，体现了在线平台在生物信息学教学与研究中的便利性。学习时应了解Mobyle平台的主要功能模块，掌握其访问方式，并理解在线分析工具在系统发育研究中的应用价值。", "page": 251, "level": "了解", "img": "assets/img/ch11/p251.jpg", "anim": null, "fig": null, "points": ["Mobyle平台由法国巴斯德研究所构建，集成了多种在线分析软件。", "包括数据库搜索、序列格式转换与编辑、序列比对和比较、系统发育分析、蛋白质序列分析、核酸序列分析以及结构分析等模块。", "系统发育分析模块提供简约法程序、距离矩阵法程序、最大似然法程序、距离计算以及系统发育树的操作与可视化等。", "用户可通过互联网在线进行系统发育分析。", "⚠️ 考点/易错点：Mobyle平台由法国巴斯德研究所构建，集成了数据库搜索、序列比对、系统发育分析等模块；易考其系统发育分析模块包含简约法、距离矩阵法、最大似然法及树的可视化工具。"], "code": null, "lang": null, "check": {"q": "Mobyle在线分析平台由哪个机构构建？", "o": ["A. 法国巴斯德研究所", "B. 美国亚利桑那州立大学", "C. 美国华盛顿大学", "D. 中国华大基因"], "a": "A", "e": "Mobyle平台由法国巴斯德研究所构建，集成了多种在线分析软件，包括系统发育分析模块。"}, "cards": [{"front": "Mobyle平台由哪个机构构建？集成了哪些分析模块？", "back": "由法国巴斯德研究所构建；集成了数据库搜索、序列格式转换与编辑、序列比对和比较、系统发育分析、蛋白质序列分析、核酸序列分析以及结构分析等模块。", "mnemonic": "巴斯德，Mobyle，多模块。", "useImg": false}]}, {"i": 25, "sec": "第三节 系统发育树构建及应用", "title": "Mobyle平台ClustalW多序列比对与Phylip距离矩阵计算", "notes": "本页展示Mobyle平台中ClustalW多序列比对和Phylip距离矩阵计算的操作界面。ClustalW用于对多条序列进行多重比对，界面中包含输入文件选择、输出格式设置等选项。用户可上传包含多条序列的文件，执行完全多重比对，并查看比对结果。页面还显示了比对结果的部分序列，如HPLARIVHDAFVQL...等氨基酸序列片段，表明该示例可能涉及蛋白质序列分析。此外，页面提及PhylipDistanceMatrix程序，用于计算距离矩阵，输出文件为dnadist.outfile。该页还包含任务管理（Jobs）、书签（Bookmarks）等导航功能。学习时应理解ClustalW在多序列比对中的作用，掌握如何通过Mobyle提交比对任务，并了解距离矩阵计算是系统发育树构建的重要步骤之一。图示界面反映了在线分析的工作流程：选择程序→输入数据→设置参数→运行→查看结果。", "page": 252, "level": "理解", "img": "assets/img/ch11/p252.jpg", "anim": null, "fig": "页面显示ClustalW操作界面和比对结果部分序列，如HPLARIVHDAFVQL...等氨基酸序列片段。", "points": ["Mobyle平台中ClustalW用于对多条序列进行多重比对。", "界面中包含输入文件选择、输出格式设置等选项。", "用户可上传包含多条序列的文件，执行完全多重比对，并查看比对结果。", "Phylip距离矩阵计算：在Mobyle平台中可计算距离矩阵，用于后续建树。", "⚠️ 考点/易错点：ClustalW用于多序列比对，Phylip Distance Matrix用于计算距离矩阵；易混点在于ClustalW是比对工具而非建树工具，距离矩阵是后续建树（如邻接法）的输入。"], "code": null, "lang": null, "check": {"q": "在Mobyle平台中，PhylipDistanceMatrix程序用于？", "o": ["A. 计算距离矩阵", "B. 多序列比对", "C. 最大似然建树", "D. 序列格式转换"], "a": "A", "e": "PhylipDistanceMatrix程序用于计算距离矩阵，是系统发育分析中距离法建树的基础步骤。"}, "cards": [{"front": "在Mobyle平台中，ClustalW用于什么？", "back": "用于对多条序列进行多重比对。", "mnemonic": "ClustalW=多序列比对。", "useImg": false}]}, {"i": 26, "sec": "第三节 系统发育树构建及应用", "title": "PhyML最大似然法建树程序选择与参数设置", "notes": "本页说明在Mobyle平台中如何选择PhyML程序进行最大似然法系统发育树构建。用户在多序列比对结果窗口下方点击“further analysis”按钮前，需先在下拉列表框中选择PhyML，然后单击该按钮，弹出PhyML程序操作页面。PhyML是一种简单、快速且准确的最大似然法估计大系统发育树的算法。页面显示PhyML操作界面包含输入选项（Input Options），如数据类型（DNA或氨基酸）、替换模型、树搜索策略等参数。用户需根据数据特点选择合适的数据类型和模型。该页还展示了任务列表，包括puzzle、phyml等任务及其运行时间。学习时应掌握PhyML的基本原理：基于最大似然法，通过优化树拓扑结构和分支长度来寻找最可能的进化树。理解在Mobyle中调用PhyML的步骤：选择程序→设置参数→提交任务→查看结果。最大似然法计算量大但统计基础坚实，适用于中小规模数据集的精确建树。", "page": 253, "level": "掌握", "img": "assets/img/ch11/p253.jpg", "anim": null, "fig": "页面显示PhyML操作界面，包含输入选项等。", "points": ["在Mobyle平台中，在多序列比对结果窗口下方点击“further analysis”按钮前，需先在下拉列表框中选择PhyML。", "单击“further analysis”按钮，弹出PhyML程序操作页面。", "PhyML是一种简单、快速且准确的最大似然法估计大系统发育树的算法。", "PhyML操作界面包含输入选项（Input Options）等参数设置。", "⚠️ 考点/易错点：PhyML是最大似然法建树程序，需在多序列比对结果窗口下方先选择PhyML再点击further analysis；易错点是数据类型（DNA或氨基酸）和替换模型必须与输入序列匹配。"], "code": null, "lang": null, "check": {"q": "在Mobyle平台中，选择PhyML程序进行最大似然法建树时，需在多序列比对结果窗口下方点击哪个按钮？", "o": ["A. further analysis", "B. Compute", "C. Align by ClustalW", "D. Bootstrap"], "a": "A", "e": "用户在多序列比对结果窗口下方点击“further analysis”按钮前，需先在下拉列表框中选择PhyML，然后单击该按钮，弹出PhyML程序操作页面。"}, "cards": [{"front": "在Mobyle平台中如何选择PhyML程序？", "back": "在多序列比对结果窗口下方点击“further analysis”按钮前，先在下拉列表框中选择PhyML，然后单击该按钮。", "mnemonic": "下拉选PhyML，点further analysis。", "useImg": false}]}, {"i": 27, "sec": "第三节 系统发育树构建及应用", "title": "PhyML运行结果与系统发育树输出", "notes": "本页展示PhyML程序运行后的输出结果。页面显示输出文件包括infile_data.phylip_phyml_tree.txt等，其中包含系统发育树的结构信息。PhyML v3.0版本运行后生成树文件，用户可保存或查看。页面还显示了部分树结构文本，如分支长度和节点信息。此外，任务列表显示phyml、puzzle、dnadist、neighbor等任务及其运行时间，表明用户可能同时运行了多种建树方法以进行比较。学习时应理解PhyML输出文件的含义：树文件通常采用Newick格式，包含拓扑结构和分支长度；日志文件记录运行参数和似然值。掌握如何解读系统发育树：分支长度代表进化距离，节点代表共同祖先，拓扑结构反映进化关系。该页还提示用户可通过Mobyle平台方便地管理和比较不同程序的结果，体现了在线平台在系统发育分析中的集成优势。", "page": 254, "level": "理解", "img": "assets/img/ch11/p254.jpg", "anim": null, "fig": "页面显示PhyML输出结果和树结构文本。", "points": ["PhyML程序运行后输出文件包括infile_data.phylip_phyml_tree.txt等。", "输出文件包含系统发育树的结构信息。", "PhyML v3.0版本运行后生成树文件，用户可保存或查看。", "页面还显示了部分树结构文本，如分支长度和节点信息。", "任务列表显示phyml、puzzle、dnadist、neighbor等任务及其运行状态。", "⚠️ 考点/易错点：PhyML输出文件如infile_data.phylip_phyml_tree.txt包含系统发育树结构；易考PhyML v3.0生成树文件，且任务列表显示可同时运行phyml、puzzle、dnadist、neighbor等多种方法进行比较。"], "code": null, "lang": null, "check": {"q": "PhyML运行后生成的树文件名称是？", "o": ["A. infile_data.phylip_phyml_tree.txt", "B. cyth.fasta", "C. alignment.aln", "D. distance.matrix"], "a": "A", "e": "PhyML程序运行后的输出文件包括infile_data.phylip_phyml_tree.txt等，其中包含系统发育树的结构信息。"}, "cards": [{"front": "PhyML运行后输出文件包括什么？", "back": "包括infile_data.phylip_phyml_tree.txt等，包含系统发育树的结构信息。", "mnemonic": "phyml_tree.txt。", "useImg": false}]}, {"i": 28, "sec": "第三节 系统发育树构建及应用", "title": "习题与参考文献", "notes": "本页包含第十一章的习题和参考文献。习题要求尝试用表11-2的数据，并选择一种建树工具进行系统进化树的构建，旨在让学生实践系统发育树构建的全过程。参考文献列出了多本生物信息学相关书籍和论文，包括李桂源等《基于WWW的生物信息学应用指南》、李建伏等《系统发生树构建技术综述》、李涛等《利用DNA序列构建系统树的方法》、王禄山等《生物信息学应用技术》、许忠能《生物信息学》、薛庆中等《DNA和蛋白质序列数据分析工具》、杨子恒《计算分子进化》等。此外还有英文文献如Bonet等关于简约法和相容性方法的改进、Brown等关于灵长类线粒体DNA序列的研究、Cavalli-Sforza和Edwards关于系统发育分析的开创性工作。学习时应了解这些参考文献是深入学习分子进化与系统发育的重要资源，并掌握系统发育树构建的基本流程：数据准备→序列比对→选择建树方法→评估树的可信度→解释结果。", "page": 255, "level": "了解", "img": "assets/img/ch11/p255.jpg", "anim": null, "fig": null, "points": ["习题：尝试用表11-2的数据，并选择一种建树工具进行系统进化树的构建。", "旨在让学生实践系统发育树构建的全过程。", "参考文献列出多本生物信息学相关书籍和论文。", "包括李桂源等《基于WWW的生物信息学应用指南》、李建伏等《系统发生树构建技术综述》等。", "⚠️ 考点/易错点：习题要求用表11-2数据选择一种建树工具构建系统进化树；易考参考文献中李桂源《基于WWW的生物信息学应用指南》等，注意区分习题实践与文献列表。"], "code": null, "lang": null, "check": {"q": "第十一章习题要求尝试用表11-2的数据，并选择一种建树工具进行什么操作？", "o": ["A. 系统进化树的构建", "B. 蛋白质结构预测", "C. 基因表达分析", "D. 代谢通路分析"], "a": "A", "e": "习题要求尝试用表11-2的数据，并选择一种建树工具进行系统进化树的构建，旨在让学生实践系统发育树构建的全过程。"}, "cards": [{"front": "第十一章习题要求用什么数据？选择什么工具？", "back": "用表11-2的数据，选择一种建树工具进行系统进化树的构建。", "mnemonic": "表11-2，任选建树工具。", "useImg": false}]}, {"i": 29, "sec": "第三节 系统发育树构建及应用", "title": "参考文献续", "notes": "本页继续列出第十一章的参考文献，包括Kimura关于分子水平进化速率的研究、King和Jukes关于非达尔文进化的论文、Krane等《生物信息学概论》、Kumar关于最小进化树逐步算法、Kumar和Gadagkar关于邻接法效率评估、Kimura关于核苷酸序列碱基替换估计的简单方法、Lakner等关于贝叶斯系统发育中马尔可夫链蒙特卡洛树提议效率等。这些文献涵盖了分子进化中性理论、系统发育树构建算法（如最小进化法、邻接法、贝叶斯推断）以及进化速率估计等核心内容。学习时应了解这些经典文献对分子进化与系统发育领域的贡献，例如Kimura的中性理论、邻接法的效率评估、贝叶斯方法在系统发育中的应用等。通过阅读这些文献，可深入理解系统发育分析的理论基础和方法学进展，为实际研究提供参考。", "page": 256, "level": "了解", "img": "assets/img/ch11/p256.jpg", "anim": null, "fig": null, "points": ["参考文献续：包括Kimura关于分子水平进化速率的研究。", "King和Jukes关于非达尔文进化的论文。", "Krane等《生物信息学概论》。", "Kumar关于最小进化树逐步算法、Kumar和Gadagkar关于邻接法效率评估。", "Kimura关于核苷酸序列碱基替换估计的简单方法、Lakner等关于贝叶斯系统发育中马尔可夫链蒙特卡洛树提议效率等。", "⚠️ 考点/易错点：本页参考文献涵盖Kimura中性理论、King和Jukes非达尔文进化、最小进化法、邻接法、贝叶斯MCMC等；易混点是Kimura的分子进化速率研究与核苷酸替换估计方法常被混淆。"], "code": null, "lang": null, "check": {"q": "下列哪篇文献涉及Kimura关于分子水平进化速率的研究？", "o": ["A. Kimura关于分子水平进化速率的研究", "B. Tamura等关于MEGA4的论文", "C. Takezaki和Nei关于最大简约法不一致性的论文", "D. Toha等关于系统发育树构建算法的论文"], "a": "A", "e": "参考文献续中包括Kimura关于分子水平进化速率的研究、King和Jukes关于非达尔文进化的论文等。"}, "cards": [{"front": "参考文献中Kimura关于分子水平进化速率的研究提出了什么？", "back": "分子水平进化速率相对恒定。", "mnemonic": "Kimura，恒速。", "useImg": false}]}, {"i": 30, "sec": "第三节 系统发育树构建及应用", "title": "系统发育分析参考文献与工具出处", "notes": "本页为第十一章第三节“系统发育树构建及应用”的参考文献页，列出系统发育与分子进化分析中若干经典论文和软件出处。内容涉及最大简约法（maximum parsimony, MP）在核苷酸替换速率恒定条件下可能出现不一致性（Takezaki & Nei, 1994）；MEGA4 分子进化遗传分析软件（Tamura et al., 2007）；系统发育树构建算法（Toha et al., 1989）；简单位点替换模型下最大似然法（maximum likelihood, ML）与最大简约法之间联系（Tuffley & Steel, 1997）；PAUP* 软件推断进化树（Wilgenbusch & Swofford, 2003）；以及 Woese 关于通用祖先（universal ancestor）的论述。学习本页的意义在于：掌握这些文献可追溯系统发育树构建方法的理论基础、软件实现和适用条件，便于在自学或研究中正确选择 MP、ML、距离法等建树策略，并理解不同方法在模型假设、计算复杂度和统计一致性上的差异。阅读时可按“方法学—软件—应用”三类整理：方法学文献解释算法原理与局限，软件文献提供操作平台，应用文献展示进化关系推断实例。", "page": 257, "level": "掌握", "img": "assets/img/ch11/p257.jpg", "anim": null, "fig": null, "points": ["参考文献页列出系统发育与分子进化分析中若干经典论文和软件出处。", "涉及最大简约法（MP）在核苷酸替换速率恒定条件下可能出现不一致性（Takezaki & Nei, 1994）。", "MEGA4分子进化遗传分析软件（Tamura et al., 2007）。", "系统发育树构建算法（T...）等。", "⚠️ 考点/易错点：本页为系统发育树构建及应用的参考文献，涉及最大简约法在核苷酸替换速率恒定下可能不一致（Takezaki & Nei, 1994）、MEGA4软件（Tamura et al., 2007）等；易考MP法的不一致性条件及MEGA4的出处。"], "code": null, "lang": null, "check": {"q": "Takezaki和Nei（1994）指出最大简约法在什么条件下可能出现不一致性？", "o": ["A. 核苷酸替换速率恒定条件下", "B. 核苷酸替换速率极快条件下", "C. 序列长度极短条件下", "D. 无插入缺失条件下"], "a": "A", "e": "参考文献页涉及最大简约法（maximum parsimony, MP）在核苷酸替换速率恒定条件下可能出现不一致性（Takezaki & Nei, 1994）。"}, "cards": [{"front": "Takezaki & Nei (1994) 的研究指出最大简约法在什么条件下可能出现不一致性？", "back": "在核苷酸替换速率恒定条件下可能出现不一致性。", "mnemonic": "MP，恒速，不一致。", "useImg": false}]}], "mcq": [{"id": "ch11_mcq_1", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于分子进化中性学说，以下哪项描述是正确的？", "o": ["A. 中性学说认为所有突变都是有害的，自然选择起主要作用", "B. 中性学说由Kimura于1968年提出，认为多数突变是中性或近中性的", "C. 中性学说认为自然选择对中性突变起决定性作用", "D. 中性学说完全否定自然选择的存在"], "a": "B", "e": "中性学说由Kimura（1968）提出，认为多数或绝大多数突变是中性或近中性的，自然选择对它们不起作用。A、C、D均与中性学说观点不符。", "kp": "ch11_s0_2"}, {"id": "ch11_mcq_2", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "UPGMA方法的基本假设是：", "o": ["A. 不同分支的进化速率可以不同", "B. 沿着树的所有分支的突变率相等", "C. 序列间没有平行进化", "D. 所有序列必须等长"], "a": "B", "e": "UPGMA建立在沿着树的所有分支的突变率相等的假设之上，因此在不同分支间进化速率有较大差异或有同源序列的平行进化时常得出错误的拓扑结构。", "kp": "ch11_s0_6"}, {"id": "ch11_mcq_3", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "在系统发育分析中，若采用基因编码序列建树，多序列比对后产生的空位数目应该是：", "o": ["A. 任意数目", "B. 2或2的倍数", "C. 3或3的倍数", "D. 4或4的倍数"], "a": "C", "e": "编码序列按三联体密码翻译，比对后空位数目应为3或3的倍数；若不是，说明比对结果不正确或无生物学意义，最好按氨基酸序列比对后调整。", "kp": "ch11_s0_21"}, {"id": "ch11_mcq_4", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "以下哪种建树方法计算速度最快？", "o": ["A. 最大似然法", "B. 最大简约法", "C. 距离法", "D. 贝叶斯法"], "a": "C", "e": "从计算速度来看，距离法最快，其次是最大简约法和贝叶斯法，然后是最大似然法。", "kp": "ch11_s0_17"}, {"id": "ch11_mcq_5", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于最大简约法（MP）的缺点，以下描述正确的是：", "o": ["A. 计算速度太慢，无法实际应用", "B. 对长枝吸引敏感，可能因趋同进化得出错误结论", "C. 不能用于序列相似性高的情况", "D. 必须选择复杂的核苷酸替代模型"], "a": "B", "e": "最大简约法没有考虑核苷酸的突变过程，长分支末端序列可能因趋同进化而显示较好相似性，趋同现象违背简约法则，导致对“长枝吸引”敏感。", "kp": "ch11_s0_12"}, {"id": "ch11_mcq_6", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "在系统发育分析中，dN > dS 通常表示：", "o": ["A. 基因经历纯化选择", "B. 基因经历正选择", "C. 基因没有发生突变", "D. 基因处于中性进化"], "a": "B", "e": "非同义替换率（dN）大于同义替换率（dS）表现为正选择，正选择更容易引起蛋白质序列改变并促进基因形成新功能；dN < dS 则为纯化选择。", "kp": "ch11_s0_19"}, {"id": "ch11_mcq_7", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于贝叶斯推断法建树，以下描述正确的是：", "o": ["A. 后验概率对先验概率不敏感", "B. 在数据量较少时往往比最大似然法更可靠", "C. 计算速度比距离法快", "D. 不需要选择进化模型"], "a": "B", "e": "贝叶斯推断法在相对参数的数据量较少时，往往可以得到比最大似然法更加可靠的结果；但后验概率对先验概率十分敏感。", "kp": "ch11_s0_15"}, {"id": "ch11_mcq_8", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "系统发育树构建的一般步骤中，第一步是：", "o": ["A. 多序列比对", "B. 选择适合的分子序列", "C. 选择适合的建树方法", "D. 系统发育树的评估"], "a": "B", "e": "构建系统发育树的4个步骤依次为：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。", "kp": "ch11_s0_16"}, {"id": "ch11_mcq_9", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于分子钟（molecular clock）假说，以下描述正确的是：", "o": ["A. 分子进化速率与表型进化速率高度相关", "B. 某蛋白质在不同物种间的取代数与分歧时间接近正线性关系", "C. 分子钟假说由Darwin提出", "D. 分子钟适用于所有生物大分子且速率完全一致"], "a": "B", "e": "Zuckerkandl和Pauling（1965）发现某蛋白质在不同物种间的取代数与所研究物种间的分歧时间接近正线性关系，提出分子钟概念。分子进化速率与表型进化速率不相关。", "kp": "ch11_s0_20"}, {"id": "ch11_mcq_10", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "当被研究的物种间进化距离比较远，DNA序列相对饱和时，建树时更好的选择是：", "o": ["A. 继续使用DNA序列", "B. 使用蛋白质序列", "C. 使用非编码区DNA序列", "D. 使用同义替换位点"], "a": "B", "e": "当物种间进化距离远、DNA序列饱和导致信息量损失时，利用蛋白质的20种氨基酸替代只有4种核苷酸的DNA，会产生比较好的效果。", "kp": "ch11_s0_17"}], "judge": [{"id": "ch11_judge_1", "modI": 0, "q": "分子进化速率与表型进化速率高度相关。", "a": "错", "e": "分子进化速率几乎恒定，且与表型进化速率不相关。", "kp": "ch11_s0_1"}, {"id": "ch11_judge_2", "modI": 0, "q": "分子钟假说认为某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。", "a": "对", "e": "Zuckerkandl和Pauling（1965）提出分子钟，即某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。", "kp": "ch11_s0_1"}, {"id": "ch11_judge_3", "modI": 0, "q": "中性学说认为多数或绝大多数突变都是有害的，自然选择对它们起主要作用。", "a": "错", "e": "中性学说认为多数或绝大多数突变都是中性或近中性的，自然选择对它们不起作用。", "kp": "ch11_s0_2"}, {"id": "ch11_judge_4", "modI": 0, "q": "UPGMA假设沿树所有分支突变率相等，适用于基因替代速率恒定时。", "a": "对", "e": "UPGMA假设沿树所有分支突变率相等，适用于基因替代速率恒定时，尤其基因频率数据。", "kp": "ch11_s0_6"}, {"id": "ch11_judge_5", "modI": 0, "q": "邻接法（NJ）通过逐步寻找使树总分支长度最大的邻居对进行合并。", "a": "错", "e": "邻接法通过逐步寻找使树总分支长度最小的邻居对进行合并。", "kp": "ch11_s0_9"}, {"id": "ch11_judge_6", "modI": 0, "q": "最大简约法基于奥卡姆剃刀原则，选择所需突变事件最少的系统发育树作为最优树。", "a": "对", "e": "最大简约法基于奥卡姆剃刀原则，选择所需突变事件最少的系统发育树作为最优树。", "kp": "ch11_s0_12"}, {"id": "ch11_judge_7", "modI": 0, "q": "最大似然法计算速度最快，适用于分类群较多的情况。", "a": "错", "e": "最大似然法计算速度最慢，分类群较多时十分费时，这是其应用的最大障碍。", "kp": "ch11_s0_14"}, {"id": "ch11_judge_8", "modI": 0, "q": "贝叶斯推断法在数据量较少时往往比最大似然法更可靠，但后验概率对先验概率十分敏感。", "a": "对", "e": "贝叶斯推断法在数据量较少时往往比最大似然法更可靠；但后验概率对先验概率十分敏感。", "kp": "ch11_s0_15"}, {"id": "ch11_judge_9", "modI": 0, "q": "多序列比对中，若采用基因编码序列建树，比对后产生的空位数目应为3或3的倍数。", "a": "对", "e": "若采用基因编码序列建树，由于核苷酸按三联体密码翻译，比对后产生的空位数目应为3或3的倍数；若空位不是3的倍数，说明比对结果不正确或无生物学意义。", "kp": "ch11_s0_17"}, {"id": "ch11_judge_10", "modI": 0, "q": "自举法通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。", "a": "对", "e": "自举法通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。支持率越高，该分支越可靠。", "kp": "ch11_s0_18"}], "fill": [{"id": "ch11_fill_1", "modI": 0, "q": "系统发育树是根据生物大分子序列差异建立的________图，用于估测物种或分子间亲缘关系、直观阐明进化历程。", "a": "树状", "kp": "ch11_s0_0"}, {"id": "ch11_fill_2", "modI": 0, "q": "Zuckerkandl和Pauling（1965）发现不同物种同一血红蛋白氨基酸随时间近似等比例置换，提出“________”，即某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。", "a": "分子钟", "kp": "ch11_s0_1"}, {"id": "ch11_fill_3", "modI": 0, "q": "Kimura（1968）提出分子进化________学说，认为多数或绝大多数突变都是中性或近中性的，自然选择对它们不起作用。", "a": "中性", "kp": "ch11_s0_2"}, {"id": "ch11_fill_4", "modI": 0, "q": "利用生物大分子数据重建系统进化树最常用的4种方法：距离法、最大简约法、最大似然法和________法。", "a": "贝叶斯", "kp": "ch11_s0_5"}, {"id": "ch11_fill_5", "modI": 0, "q": "UPGMA算法从距离矩阵中最小距离的一对序列开始聚合，分支点为该距离的________。", "a": "一半", "kp": "ch11_s0_6"}, {"id": "ch11_fill_6", "modI": 0, "q": "邻接法（NJ）通过逐步寻找使树总分支长度最小的________进行合并，计算速度较快，适用于序列相似性较高的情况。", "a": "邻居对", "kp": "ch11_s0_17"}, {"id": "ch11_fill_7", "modI": 0, "q": "最大简约法基于________原则，选择所需突变事件最少的系统发育树作为最优树。", "a": "奥卡姆剃刀", "kp": "ch11_s0_12"}, {"id": "ch11_fill_8", "modI": 0, "q": "构建系统发育树一般分为4个步骤：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的________。", "a": "评估", "kp": "ch11_s0_16"}], "short": [{"id": "ch11_short_1", "modI": 0, "q": "简述分子进化的两大特点。", "a": "①进化速率相对恒定：以核酸或蛋白质一级结构中核苷酸/氨基酸替换数作为进化改变量，以年为时间单位，分子进化速率几乎恒定，且与表型进化速率不相关；Zuckerkandl和Pauling提出“分子钟”，即某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。②进化的保守性：功能重要的大分子或局部进化速率明显低于功能不重要者，如密码子同义替换频率高于变义替换，内含子替换速率高，假基因更高，说明分子进化并非完全随机。", "kp": "ch11_s0_1"}, {"id": "ch11_short_2", "modI": 0, "q": "简述UPGMA的基本原理与算法。", "a": "UPGMA是最简单的基于距离的建树方法。基本思想：先通过两两比对计算遗传距离，再对距离进行合并并重新计算，作为进化树分枝长度，最后绘制进化树。算法从距离矩阵中最小距离的一对序列开始聚合，分支点为该距离的一半；合并后的集合与另一序列k的距离为两集合间所有序列对距离的平均值。两个集合A和B间距离d_AB=Σd_ij/(rs)，r、s分别为集合内序列数，分支点为d_AB/2。UPGMA假设沿树所有分支突变率相等，适用于基因替代速率恒定时，尤其基因频率数据；若不同分支进化速率差异大或有平行进化，常得出错误拓扑结构。", "kp": "ch11_s0_6"}, {"id": "ch11_short_3", "modI": 0, "q": "简述构建系统发育树的四个步骤。", "a": "①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。选择分子序列时，DNA序列通常比蛋白质序列包含更多信息量，可获取同义/非同义替换信息，通过比较非同义替换率（dN）和同义替换率（dS）判断正选择或纯化选择；非编码区受选择压力小，也可用于建树。多序列比对是基础步骤和关键环节，错误比对生成的树没有生物学意义。建树方法选择需考虑计算速度和数据特点。系统发育树评估用于检验分支支持强度。", "kp": "ch11_s0_16"}, {"id": "ch11_short_4", "modI": 0, "q": "简述多序列比对的注意事项。", "a": "多序列比对是系统发育分析的基础步骤和关键环节，比对结果直接影响分析结论。若采用基因编码序列建树，由于核苷酸按三联体密码翻译，比对后产生的空位数目应为3或3的倍数；若空位不是3的倍数，说明比对结果不正确或无生物学意义，最好按氨基酸序列比对后相应调整核苷酸比对结果。根据二级或三级序列结构进行比对比直接利用一级序列更可信，因为复杂结构保守性高于简单特征的同源保守性，还可搜索特殊关联位点。例如核糖体基因二级结构通常为茎环（stem loop）结构，茎区多保守，环区高度可变。当序列分歧度大或有大的插入/缺失（indel）片段时，处理这些位点取决于进化模型要素，相关参数在前导树与比对推导的进化树中应保持一致。", "kp": "ch11_s0_22"}, {"id": "ch11_short_5", "modI": 0, "q": "简述系统发育树的评估方法。", "a": "系统发育树构建后需要评估其可靠性和分支支持强度。常用评估方法包括自举法（bootstrap）、刀切法（jackknife）等。自举法通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。支持率越高，该分支越可靠。贝叶斯推断法直接给出后验概率作为分支支持强度。评估时应注意：支持率低的分支可能因数据信息不足或方法不当导致，需结合生物学知识判断。系统发育树的评估是构建步骤的最后一环，确保所推断的进化关系具有统计学支持。", "kp": "ch11_s0_5"}], "calc": [{"id": "ch11_calc_1", "modI": 0, "q": "论述四类建树方法及适用范围，并比较其计算速度。", "a": "利用生物大分子数据重建系统进化树最常用的有4种方法：距离法、最大简约法、最大似然法和贝叶斯法。最大简约法主要适用于序列相似性很高的情况；距离法在序列具有较高相似性时适用；最大似然法和贝叶斯法可用于任何相关的数据序列集合。从计算速度看，距离法最快，其次是最大简约法和贝叶斯法，然后是最大似然法。实际应用中需兼顾计算速度、分子数据特点和方法适用范围。距离法是纯数学算法，通过序列两两差异决定拓扑结构和枝长，将建树和最优树确定融合，但转换为距离矩阵时会丢失部分进化信息。最大简约法和最大似然法从数学角度评价树的最优标准，寻找使目标函数最优的树。贝叶斯法在数据量较少时往往比最大似然法更可靠，但后验概率对先验概率敏感。", "steps": "①列出四类方法；②分别说明适用范围；③比较计算速度；④补充距离法、最大简约法、最大似然法、贝叶斯法的特点。", "kp": "ch11_s0_17"}, {"id": "ch11_calc_2", "modI": 0, "q": "论述分子序列的选择：DNA与蛋白质序列在系统发育分析中的优缺点。", "a": "系统发育树可用DNA、RNA或蛋白质序列数据构建。通常DNA序列信息量比蛋白质序列多，利用DNA序列更精确，原因包括：①编码区可发生同义或非同义替换，DNA序列既能获取引起氨基酸改变的非同义替换信息，也能获得不引起氨基酸改变的同义替换信息；②通过比较非同义替换率（dN）和同义替换率（dS）可显示基因经历正选择还是纯化选择，纯化选择表现为dN<dS，正选择表现为dN>dS；③非编码区受较小进化选择压力，发生更多中性突变，也可用于建树；④DNA序列还可估计转换和颠换速率。当基因改变非常慢或物种亲缘关系非常近时，DNA序列是较好选择；当物种间进化距离远、DNA序列饱和时，蛋白质的20种氨基酸比4种核苷酸效果更好。", "steps": "①说明DNA与蛋白质序列均可用于建树；②列举DNA序列信息量多的原因；③说明dN/dS判断选择类型；④指出非编码区特点；⑤说明DNA与蛋白质的适用条件。", "kp": "ch11_s0_16"}], "term": [{"id": "ch11_term_1", "modI": 0, "term": "Molecular Evolution", "def": "分子进化：生物进化过程中蛋白质、核酸等生物大分子在分子水平上的演变，是生物进化最基础层次上的进化。DNA可发生插入、缺失、倒位、替换等变异；若变异片段编码多肽，可能改变氨基酸序列。分子序列相对稳定、信息量大，比形态和生理特征更能可靠推断物种间系统发育关系。", "kp": "ch11_s0_20"}, {"id": "ch11_term_2", "modI": 0, "term": "Phylogenetic Tree", "def": "系统发育树：根据生物大分子序列差异建立的树状图，用于估测物种或分子间亲缘关系、直观阐明进化历程。重建“生命之树”是进化生物学的重要目标。", "kp": "ch11_s0_27"}, {"id": "ch11_term_3", "modI": 0, "term": "Molecular Clock", "def": "分子钟：Zuckerkandl和Pauling（1965）提出，指某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。以核酸或蛋白质一级结构中核苷酸/氨基酸替换数作为进化改变量，以年为时间单位，分子进化速率几乎恒定，且与表型进化速率不相关。", "kp": "ch11_s0_25"}, {"id": "ch11_term_4", "modI": 0, "term": "Neutral Theory of Molecular Evolution", "def": "分子进化中性学说：Kimura（1968）提出，认为多数或绝大多数突变都是中性或近中性的，无所谓有利或不利，自然选择对它们不起作用，因此这些中性突变不会发生自然选择与适者生存的情况。能解释种内广泛多态性、DNA哺乳动物种系总变异速率远高于形态变异速率等现象。", "kp": "ch11_s0_20"}, {"id": "ch11_term_5", "modI": 0, "term": "UPGMA", "def": "非加权分组平均法：最简单的基于距离的建树方法，由Sokal和Michener（1958）提出，Sneath和Sokal（1973）改良。先通过两两比对计算遗传距离，再对距离进行合并并重新计算，作为进化树分枝长度，最后绘制进化树。从距离矩阵中最小距离的一对序列开始聚合，分支点为该距离的一半；合并后的集合与另一序列k的距离为两集合间所有序列对距离的平均值。假设沿树所有分支突变率相等，适用于基因替代速率恒定时，尤其基因频率数据；若不同分支进化速率差异大或有平行进化，常得出错误拓扑结构。", "kp": "ch11_s0_6"}, {"id": "ch11_term_6", "modI": 0, "term": "Neighbor-Joining (NJ)", "def": "邻接法：常用的基于距离的建树方法，由Saitou和Nei提出，通过逐步寻找使树总分支长度最小的邻居对进行合并，计算速度较快，适用于序列相似性较高的情况。", "kp": "ch11_s0_9"}, {"id": "ch11_term_7", "modI": 0, "term": "Maximum Parsimony (MP)", "def": "最大简约法：基于奥卡姆剃刀原则，选择所需突变事件最少的系统发育树作为最优树。主要适用于序列相似性很高的情况，能快速分析序列间系统发育关系，所构建树中的短分支更接近真实。但当DNA序列进化速率在不同分支上相差很大或亲缘关系太远时，单一突变图谱可能得出似是而非的结论。由于没有考虑核苷酸突变过程，长分支末端序列可能因趋同进化而显示较好相似性，趋同现象违背简约法则，导致对“长枝吸引”敏感。", "kp": "ch11_s0_11"}, {"id": "ch11_term_8", "modI": 0, "term": "Maximum Likelihood (ML)", "def": "最大似然法：充分考虑了所有可能的突变路径，能完全利用数据的系统发育信息，可用于任何相关的数据序列集合。其核心在于对核苷酸替代模型的选择，不同位点核苷酸替代速率不一致，模型中包含反映进化过程的参数，但并非模型越复杂结果越理想。由于计算每个树的似然值及基于最优标准算法复杂，分类群较多时十分费时，这是其应用的最大障碍。", "kp": "ch11_s0_13"}, {"id": "ch11_term_9", "modI": 0, "term": "Bayesian Inference", "def": "贝叶斯推断法：分析结果取决于所有可能参数值，寻找对参数的最广泛支持，在数据量较少时往往比最大似然法更可靠；但后验概率对先验概率十分敏感。", "kp": "ch11_s0_15"}, {"id": "ch11_term_10", "modI": 0, "term": "Bootstrap", "def": "自举法：系统发育树评估的常用方法，通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。支持率越高，该分支越可靠。", "kp": "ch11_s0_23"}, {"id": "ch11_term_11", "modI": 0, "term": "dN/dS", "def": "非同义替换率与同义替换率之比：通过比较非同义替换率（dN）和同义替换率（dS）可显示基因经历正选择还是纯化选择，纯化选择表现为dN<dS，正选择表现为dN>dS。", "kp": "ch11_s0_16"}, {"id": "ch11_term_12", "modI": 0, "term": "MEGA", "def": "Molecular Evolutionary Genetics Analysis：常用的集成软件，可进行多序列比对、距离计算、建树（NJ、MP、ML等）和树评估，界面友好，适合教学和常规分析。", "kp": "ch11_s0_20"}]}], "mcq": [{"id": "ch11_mcq_1", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于分子进化中性学说，以下哪项描述是正确的？", "o": ["A. 中性学说认为所有突变都是有害的，自然选择起主要作用", "B. 中性学说由Kimura于1968年提出，认为多数突变是中性或近中性的", "C. 中性学说认为自然选择对中性突变起决定性作用", "D. 中性学说完全否定自然选择的存在"], "a": "B", "e": "中性学说由Kimura（1968）提出，认为多数或绝大多数突变是中性或近中性的，自然选择对它们不起作用。A、C、D均与中性学说观点不符。", "kp": "ch11_s0_2"}, {"id": "ch11_mcq_2", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "UPGMA方法的基本假设是：", "o": ["A. 不同分支的进化速率可以不同", "B. 沿着树的所有分支的突变率相等", "C. 序列间没有平行进化", "D. 所有序列必须等长"], "a": "B", "e": "UPGMA建立在沿着树的所有分支的突变率相等的假设之上，因此在不同分支间进化速率有较大差异或有同源序列的平行进化时常得出错误的拓扑结构。", "kp": "ch11_s0_6"}, {"id": "ch11_mcq_3", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "在系统发育分析中，若采用基因编码序列建树，多序列比对后产生的空位数目应该是：", "o": ["A. 任意数目", "B. 2或2的倍数", "C. 3或3的倍数", "D. 4或4的倍数"], "a": "C", "e": "编码序列按三联体密码翻译，比对后空位数目应为3或3的倍数；若不是，说明比对结果不正确或无生物学意义，最好按氨基酸序列比对后调整。", "kp": "ch11_s0_21"}, {"id": "ch11_mcq_4", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "以下哪种建树方法计算速度最快？", "o": ["A. 最大似然法", "B. 最大简约法", "C. 距离法", "D. 贝叶斯法"], "a": "C", "e": "从计算速度来看，距离法最快，其次是最大简约法和贝叶斯法，然后是最大似然法。", "kp": "ch11_s0_17"}, {"id": "ch11_mcq_5", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于最大简约法（MP）的缺点，以下描述正确的是：", "o": ["A. 计算速度太慢，无法实际应用", "B. 对长枝吸引敏感，可能因趋同进化得出错误结论", "C. 不能用于序列相似性高的情况", "D. 必须选择复杂的核苷酸替代模型"], "a": "B", "e": "最大简约法没有考虑核苷酸的突变过程，长分支末端序列可能因趋同进化而显示较好相似性，趋同现象违背简约法则，导致对“长枝吸引”敏感。", "kp": "ch11_s0_12"}, {"id": "ch11_mcq_6", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "在系统发育分析中，dN > dS 通常表示：", "o": ["A. 基因经历纯化选择", "B. 基因经历正选择", "C. 基因没有发生突变", "D. 基因处于中性进化"], "a": "B", "e": "非同义替换率（dN）大于同义替换率（dS）表现为正选择，正选择更容易引起蛋白质序列改变并促进基因形成新功能；dN < dS 则为纯化选择。", "kp": "ch11_s0_19"}, {"id": "ch11_mcq_7", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于贝叶斯推断法建树，以下描述正确的是：", "o": ["A. 后验概率对先验概率不敏感", "B. 在数据量较少时往往比最大似然法更可靠", "C. 计算速度比距离法快", "D. 不需要选择进化模型"], "a": "B", "e": "贝叶斯推断法在相对参数的数据量较少时，往往可以得到比最大似然法更加可靠的结果；但后验概率对先验概率十分敏感。", "kp": "ch11_s0_15"}, {"id": "ch11_mcq_8", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "系统发育树构建的一般步骤中，第一步是：", "o": ["A. 多序列比对", "B. 选择适合的分子序列", "C. 选择适合的建树方法", "D. 系统发育树的评估"], "a": "B", "e": "构建系统发育树的4个步骤依次为：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。", "kp": "ch11_s0_16"}, {"id": "ch11_mcq_9", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "关于分子钟（molecular clock）假说，以下描述正确的是：", "o": ["A. 分子进化速率与表型进化速率高度相关", "B. 某蛋白质在不同物种间的取代数与分歧时间接近正线性关系", "C. 分子钟假说由Darwin提出", "D. 分子钟适用于所有生物大分子且速率完全一致"], "a": "B", "e": "Zuckerkandl和Pauling（1965）发现某蛋白质在不同物种间的取代数与所研究物种间的分歧时间接近正线性关系，提出分子钟概念。分子进化速率与表型进化速率不相关。", "kp": "ch11_s0_20"}, {"id": "ch11_mcq_10", "mod": "第十一章 分子进化与系统发育", "modI": 0, "q": "当被研究的物种间进化距离比较远，DNA序列相对饱和时，建树时更好的选择是：", "o": ["A. 继续使用DNA序列", "B. 使用蛋白质序列", "C. 使用非编码区DNA序列", "D. 使用同义替换位点"], "a": "B", "e": "当物种间进化距离远、DNA序列饱和导致信息量损失时，利用蛋白质的20种氨基酸替代只有4种核苷酸的DNA，会产生比较好的效果。", "kp": "ch11_s0_17"}], "judge": [{"id": "ch11_judge_1", "modI": 0, "q": "分子进化速率与表型进化速率高度相关。", "a": "错", "e": "分子进化速率几乎恒定，且与表型进化速率不相关。", "kp": "ch11_s0_1"}, {"id": "ch11_judge_2", "modI": 0, "q": "分子钟假说认为某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。", "a": "对", "e": "Zuckerkandl和Pauling（1965）提出分子钟，即某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。", "kp": "ch11_s0_1"}, {"id": "ch11_judge_3", "modI": 0, "q": "中性学说认为多数或绝大多数突变都是有害的，自然选择对它们起主要作用。", "a": "错", "e": "中性学说认为多数或绝大多数突变都是中性或近中性的，自然选择对它们不起作用。", "kp": "ch11_s0_2"}, {"id": "ch11_judge_4", "modI": 0, "q": "UPGMA假设沿树所有分支突变率相等，适用于基因替代速率恒定时。", "a": "对", "e": "UPGMA假设沿树所有分支突变率相等，适用于基因替代速率恒定时，尤其基因频率数据。", "kp": "ch11_s0_6"}, {"id": "ch11_judge_5", "modI": 0, "q": "邻接法（NJ）通过逐步寻找使树总分支长度最大的邻居对进行合并。", "a": "错", "e": "邻接法通过逐步寻找使树总分支长度最小的邻居对进行合并。", "kp": "ch11_s0_9"}, {"id": "ch11_judge_6", "modI": 0, "q": "最大简约法基于奥卡姆剃刀原则，选择所需突变事件最少的系统发育树作为最优树。", "a": "对", "e": "最大简约法基于奥卡姆剃刀原则，选择所需突变事件最少的系统发育树作为最优树。", "kp": "ch11_s0_12"}, {"id": "ch11_judge_7", "modI": 0, "q": "最大似然法计算速度最快，适用于分类群较多的情况。", "a": "错", "e": "最大似然法计算速度最慢，分类群较多时十分费时，这是其应用的最大障碍。", "kp": "ch11_s0_14"}, {"id": "ch11_judge_8", "modI": 0, "q": "贝叶斯推断法在数据量较少时往往比最大似然法更可靠，但后验概率对先验概率十分敏感。", "a": "对", "e": "贝叶斯推断法在数据量较少时往往比最大似然法更可靠；但后验概率对先验概率十分敏感。", "kp": "ch11_s0_15"}, {"id": "ch11_judge_9", "modI": 0, "q": "多序列比对中，若采用基因编码序列建树，比对后产生的空位数目应为3或3的倍数。", "a": "对", "e": "若采用基因编码序列建树，由于核苷酸按三联体密码翻译，比对后产生的空位数目应为3或3的倍数；若空位不是3的倍数，说明比对结果不正确或无生物学意义。", "kp": "ch11_s0_17"}, {"id": "ch11_judge_10", "modI": 0, "q": "自举法通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。", "a": "对", "e": "自举法通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。支持率越高，该分支越可靠。", "kp": "ch11_s0_18"}], "fill": [{"id": "ch11_fill_1", "modI": 0, "q": "系统发育树是根据生物大分子序列差异建立的________图，用于估测物种或分子间亲缘关系、直观阐明进化历程。", "a": "树状", "kp": "ch11_s0_0"}, {"id": "ch11_fill_2", "modI": 0, "q": "Zuckerkandl和Pauling（1965）发现不同物种同一血红蛋白氨基酸随时间近似等比例置换，提出“________”，即某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。", "a": "分子钟", "kp": "ch11_s0_1"}, {"id": "ch11_fill_3", "modI": 0, "q": "Kimura（1968）提出分子进化________学说，认为多数或绝大多数突变都是中性或近中性的，自然选择对它们不起作用。", "a": "中性", "kp": "ch11_s0_2"}, {"id": "ch11_fill_4", "modI": 0, "q": "利用生物大分子数据重建系统进化树最常用的4种方法：距离法、最大简约法、最大似然法和________法。", "a": "贝叶斯", "kp": "ch11_s0_5"}, {"id": "ch11_fill_5", "modI": 0, "q": "UPGMA算法从距离矩阵中最小距离的一对序列开始聚合，分支点为该距离的________。", "a": "一半", "kp": "ch11_s0_6"}, {"id": "ch11_fill_6", "modI": 0, "q": "邻接法（NJ）通过逐步寻找使树总分支长度最小的________进行合并，计算速度较快，适用于序列相似性较高的情况。", "a": "邻居对", "kp": "ch11_s0_17"}, {"id": "ch11_fill_7", "modI": 0, "q": "最大简约法基于________原则，选择所需突变事件最少的系统发育树作为最优树。", "a": "奥卡姆剃刀", "kp": "ch11_s0_12"}, {"id": "ch11_fill_8", "modI": 0, "q": "构建系统发育树一般分为4个步骤：①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的________。", "a": "评估", "kp": "ch11_s0_16"}], "short": [{"id": "ch11_short_1", "modI": 0, "q": "简述分子进化的两大特点。", "a": "①进化速率相对恒定：以核酸或蛋白质一级结构中核苷酸/氨基酸替换数作为进化改变量，以年为时间单位，分子进化速率几乎恒定，且与表型进化速率不相关；Zuckerkandl和Pauling提出“分子钟”，即某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。②进化的保守性：功能重要的大分子或局部进化速率明显低于功能不重要者，如密码子同义替换频率高于变义替换，内含子替换速率高，假基因更高，说明分子进化并非完全随机。", "kp": "ch11_s0_1"}, {"id": "ch11_short_2", "modI": 0, "q": "简述UPGMA的基本原理与算法。", "a": "UPGMA是最简单的基于距离的建树方法。基本思想：先通过两两比对计算遗传距离，再对距离进行合并并重新计算，作为进化树分枝长度，最后绘制进化树。算法从距离矩阵中最小距离的一对序列开始聚合，分支点为该距离的一半；合并后的集合与另一序列k的距离为两集合间所有序列对距离的平均值。两个集合A和B间距离d_AB=Σd_ij/(rs)，r、s分别为集合内序列数，分支点为d_AB/2。UPGMA假设沿树所有分支突变率相等，适用于基因替代速率恒定时，尤其基因频率数据；若不同分支进化速率差异大或有平行进化，常得出错误拓扑结构。", "kp": "ch11_s0_6"}, {"id": "ch11_short_3", "modI": 0, "q": "简述构建系统发育树的四个步骤。", "a": "①选择适合的分子序列；②多序列比对；③选择适合的建树方法；④系统发育树的评估。选择分子序列时，DNA序列通常比蛋白质序列包含更多信息量，可获取同义/非同义替换信息，通过比较非同义替换率（dN）和同义替换率（dS）判断正选择或纯化选择；非编码区受选择压力小，也可用于建树。多序列比对是基础步骤和关键环节，错误比对生成的树没有生物学意义。建树方法选择需考虑计算速度和数据特点。系统发育树评估用于检验分支支持强度。", "kp": "ch11_s0_16"}, {"id": "ch11_short_4", "modI": 0, "q": "简述多序列比对的注意事项。", "a": "多序列比对是系统发育分析的基础步骤和关键环节，比对结果直接影响分析结论。若采用基因编码序列建树，由于核苷酸按三联体密码翻译，比对后产生的空位数目应为3或3的倍数；若空位不是3的倍数，说明比对结果不正确或无生物学意义，最好按氨基酸序列比对后相应调整核苷酸比对结果。根据二级或三级序列结构进行比对比直接利用一级序列更可信，因为复杂结构保守性高于简单特征的同源保守性，还可搜索特殊关联位点。例如核糖体基因二级结构通常为茎环（stem loop）结构，茎区多保守，环区高度可变。当序列分歧度大或有大的插入/缺失（indel）片段时，处理这些位点取决于进化模型要素，相关参数在前导树与比对推导的进化树中应保持一致。", "kp": "ch11_s0_22"}, {"id": "ch11_short_5", "modI": 0, "q": "简述系统发育树的评估方法。", "a": "系统发育树构建后需要评估其可靠性和分支支持强度。常用评估方法包括自举法（bootstrap）、刀切法（jackknife）等。自举法通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。支持率越高，该分支越可靠。贝叶斯推断法直接给出后验概率作为分支支持强度。评估时应注意：支持率低的分支可能因数据信息不足或方法不当导致，需结合生物学知识判断。系统发育树的评估是构建步骤的最后一环，确保所推断的进化关系具有统计学支持。", "kp": "ch11_s0_5"}], "calc": [{"id": "ch11_calc_1", "modI": 0, "q": "论述四类建树方法及适用范围，并比较其计算速度。", "a": "利用生物大分子数据重建系统进化树最常用的有4种方法：距离法、最大简约法、最大似然法和贝叶斯法。最大简约法主要适用于序列相似性很高的情况；距离法在序列具有较高相似性时适用；最大似然法和贝叶斯法可用于任何相关的数据序列集合。从计算速度看，距离法最快，其次是最大简约法和贝叶斯法，然后是最大似然法。实际应用中需兼顾计算速度、分子数据特点和方法适用范围。距离法是纯数学算法，通过序列两两差异决定拓扑结构和枝长，将建树和最优树确定融合，但转换为距离矩阵时会丢失部分进化信息。最大简约法和最大似然法从数学角度评价树的最优标准，寻找使目标函数最优的树。贝叶斯法在数据量较少时往往比最大似然法更可靠，但后验概率对先验概率敏感。", "steps": "①列出四类方法；②分别说明适用范围；③比较计算速度；④补充距离法、最大简约法、最大似然法、贝叶斯法的特点。", "kp": "ch11_s0_17"}, {"id": "ch11_calc_2", "modI": 0, "q": "论述分子序列的选择：DNA与蛋白质序列在系统发育分析中的优缺点。", "a": "系统发育树可用DNA、RNA或蛋白质序列数据构建。通常DNA序列信息量比蛋白质序列多，利用DNA序列更精确，原因包括：①编码区可发生同义或非同义替换，DNA序列既能获取引起氨基酸改变的非同义替换信息，也能获得不引起氨基酸改变的同义替换信息；②通过比较非同义替换率（dN）和同义替换率（dS）可显示基因经历正选择还是纯化选择，纯化选择表现为dN<dS，正选择表现为dN>dS；③非编码区受较小进化选择压力，发生更多中性突变，也可用于建树；④DNA序列还可估计转换和颠换速率。当基因改变非常慢或物种亲缘关系非常近时，DNA序列是较好选择；当物种间进化距离远、DNA序列饱和时，蛋白质的20种氨基酸比4种核苷酸效果更好。", "steps": "①说明DNA与蛋白质序列均可用于建树；②列举DNA序列信息量多的原因；③说明dN/dS判断选择类型；④指出非编码区特点；⑤说明DNA与蛋白质的适用条件。", "kp": "ch11_s0_16"}], "term": [{"id": "ch11_term_1", "modI": 0, "term": "Molecular Evolution", "def": "分子进化：生物进化过程中蛋白质、核酸等生物大分子在分子水平上的演变，是生物进化最基础层次上的进化。DNA可发生插入、缺失、倒位、替换等变异；若变异片段编码多肽，可能改变氨基酸序列。分子序列相对稳定、信息量大，比形态和生理特征更能可靠推断物种间系统发育关系。", "kp": "ch11_s0_20"}, {"id": "ch11_term_2", "modI": 0, "term": "Phylogenetic Tree", "def": "系统发育树：根据生物大分子序列差异建立的树状图，用于估测物种或分子间亲缘关系、直观阐明进化历程。重建“生命之树”是进化生物学的重要目标。", "kp": "ch11_s0_27"}, {"id": "ch11_term_3", "modI": 0, "term": "Molecular Clock", "def": "分子钟：Zuckerkandl和Pauling（1965）提出，指某蛋白质在不同物种间的取代数与分歧时间接近正线性关系。以核酸或蛋白质一级结构中核苷酸/氨基酸替换数作为进化改变量，以年为时间单位，分子进化速率几乎恒定，且与表型进化速率不相关。", "kp": "ch11_s0_25"}, {"id": "ch11_term_4", "modI": 0, "term": "Neutral Theory of Molecular Evolution", "def": "分子进化中性学说：Kimura（1968）提出，认为多数或绝大多数突变都是中性或近中性的，无所谓有利或不利，自然选择对它们不起作用，因此这些中性突变不会发生自然选择与适者生存的情况。能解释种内广泛多态性、DNA哺乳动物种系总变异速率远高于形态变异速率等现象。", "kp": "ch11_s0_20"}, {"id": "ch11_term_5", "modI": 0, "term": "UPGMA", "def": "非加权分组平均法：最简单的基于距离的建树方法，由Sokal和Michener（1958）提出，Sneath和Sokal（1973）改良。先通过两两比对计算遗传距离，再对距离进行合并并重新计算，作为进化树分枝长度，最后绘制进化树。从距离矩阵中最小距离的一对序列开始聚合，分支点为该距离的一半；合并后的集合与另一序列k的距离为两集合间所有序列对距离的平均值。假设沿树所有分支突变率相等，适用于基因替代速率恒定时，尤其基因频率数据；若不同分支进化速率差异大或有平行进化，常得出错误拓扑结构。", "kp": "ch11_s0_6"}, {"id": "ch11_term_6", "modI": 0, "term": "Neighbor-Joining (NJ)", "def": "邻接法：常用的基于距离的建树方法，由Saitou和Nei提出，通过逐步寻找使树总分支长度最小的邻居对进行合并，计算速度较快，适用于序列相似性较高的情况。", "kp": "ch11_s0_9"}, {"id": "ch11_term_7", "modI": 0, "term": "Maximum Parsimony (MP)", "def": "最大简约法：基于奥卡姆剃刀原则，选择所需突变事件最少的系统发育树作为最优树。主要适用于序列相似性很高的情况，能快速分析序列间系统发育关系，所构建树中的短分支更接近真实。但当DNA序列进化速率在不同分支上相差很大或亲缘关系太远时，单一突变图谱可能得出似是而非的结论。由于没有考虑核苷酸突变过程，长分支末端序列可能因趋同进化而显示较好相似性，趋同现象违背简约法则，导致对“长枝吸引”敏感。", "kp": "ch11_s0_11"}, {"id": "ch11_term_8", "modI": 0, "term": "Maximum Likelihood (ML)", "def": "最大似然法：充分考虑了所有可能的突变路径，能完全利用数据的系统发育信息，可用于任何相关的数据序列集合。其核心在于对核苷酸替代模型的选择，不同位点核苷酸替代速率不一致，模型中包含反映进化过程的参数，但并非模型越复杂结果越理想。由于计算每个树的似然值及基于最优标准算法复杂，分类群较多时十分费时，这是其应用的最大障碍。", "kp": "ch11_s0_13"}, {"id": "ch11_term_9", "modI": 0, "term": "Bayesian Inference", "def": "贝叶斯推断法：分析结果取决于所有可能参数值，寻找对参数的最广泛支持，在数据量较少时往往比最大似然法更可靠；但后验概率对先验概率十分敏感。", "kp": "ch11_s0_15"}, {"id": "ch11_term_10", "modI": 0, "term": "Bootstrap", "def": "自举法：系统发育树评估的常用方法，通过对原始比对序列进行有放回重采样，生成多组伪重复数据集，分别建树后统计各分支出现的频率，作为分支支持率。支持率越高，该分支越可靠。", "kp": "ch11_s0_23"}, {"id": "ch11_term_11", "modI": 0, "term": "dN/dS", "def": "非同义替换率与同义替换率之比：通过比较非同义替换率（dN）和同义替换率（dS）可显示基因经历正选择还是纯化选择，纯化选择表现为dN<dS，正选择表现为dN>dS。", "kp": "ch11_s0_16"}, {"id": "ch11_term_12", "modI": 0, "term": "MEGA", "def": "Molecular Evolutionary Genetics Analysis：常用的集成软件，可进行多序列比对、距离计算、建树（NJ、MP、ML等）和树评估，界面友好，适合教学和常规分析。", "kp": "ch11_s0_20"}], "preview": {"main": "本章从达尔文进化论与“生命之树”出发，介绍分子进化的两大特点——进化速率相对恒定与保守性，以及中性学说、基因组计划对分子进化研究的推动。重点讲解系统发育树的有根/无根概念，以及UPGMA、邻接法、最大简约法、最大似然法等建树方法的原理与步骤，并结合MEGA、PHYLIP、PAUP、Mobyle等工具说明从序列选择、多序列比对、建树到可靠性评估的完整流程。", "questions": ["为什么分子进化速率可以近似恒定？这与“分子钟”和建树方法有什么关系？", "有根树和无根树有什么区别？全生命系统树的根代表什么？", "UPGMA、邻接法、最大简约法和最大似然法各自依据什么原则建树？分别适合什么数据？", "构建系统发育树的四个基本步骤是什么？多序列比对时为什么要参考二级结构？", "如何用自展法或折刀法评估系统发育树的可靠性？支持率低说明什么？"]}, "appcards": [{"front": "为什么说分子进化速率相对恒定？这一特点对系统发育树构建有什么意义？", "back": "①以核酸/蛋白质一级结构中核苷酸或氨基酸替换数为进化改变量，以年为单位，生物大分子随时间的改变即分子进化速率几乎恒定；②一级结构改变只与进化经历时间相关，与表型进化速率不相关；③可能解释是分子序列中多数替换为中性或近中性突变，受选择压力较小；④意义：为“分子钟”假设提供基础，使系统发育树可按分支长度反映时间或遗传距离，是距离法、UPGMA、NJ等建树方法的前提。", "points": "分子进化速率相对恒定；替换数与时间相关、与表型不相关；中性突变解释；分子钟；建树前提", "mod": 0, "modName": "第十一章 分子进化与系统发育", "level": "掌握", "src": "生成"}, {"front": "UPGMA、邻接法（NJ）、最大简约法（MP）、最大似然法（ML）的基本原理和适用特点有何不同？", "back": "①UPGMA：基于距离矩阵，每次合并距离最小的一对，分支点高度为d/2，新集合距离按算术平均更新；假设进化速率恒定，适合近似等速进化数据。②NJ：基于最小进化原则，计算净分歧度ri和速率校正距离Mij=dij-(ri+rj)/(N-2)，选择Mij最小者归并，使整棵树总枝长最小；不要求严格等速，较常用。③MP：基于奥卡姆剃刀，选择解释性状变化所需替换数最少、树长最小的拓扑；适合序列分歧较小、信息位点较多的情况。④ML：在特定替代模型下计算各拓扑的似然值，选择似然值最大的树；统计基础强但计算量大。", "points": "UPGMA距离最小合并、d/2、算术平均；NJ最小进化、Mij、总枝长最小；MP奥卡姆剃刀、最少替换、树长；ML替代模型、最大似然值", "mod": 0, "modName": "第十一章 分子进化与系统发育", "level": "掌握", "src": "生成"}, {"front": "构建一棵分子系统发育树通常包括哪些步骤？每一步的关键注意点是什么？", "back": "①选择适合的分子序列：可用DNA、RNA或蛋白质序列；DNA信息量通常比蛋白质多、更精确；应选同源序列，并考虑进化速率和保守性。②多序列比对：根据二级或三级结构比对更可信；如rRNA茎环结构中茎区保守、环区可变；分歧大或有插入/缺失时需选择合适比对策略。③选择建树方法：根据数据特点、进化速率假设和计算资源选择UPGMA、NJ、MP、ML或贝叶斯等。④系统发育树评估：用自展法或折刀法重复抽样检验，统计内部分支支持率，排除随机误差影响。", "points": "选序列；多序列比对；选建树方法；树评估；同源、结构比对、自展/折刀、支持率", "mod": 0, "modName": "第十一章 分子进化与系统发育", "level": "掌握", "src": "生成"}, {"front": "如何评估系统发育树的可靠性？自展法和折刀法的作用是什么？", "back": "①距离法、MP或ML得到的树只是点估计，需加可靠性测度；②自展检验：从原始数据集中随机重采样产生伪数据集（自展样本），对每个自展样本用相同建树方法建树，重复成百上千次；③统计最终树中内部分支在自展树中出现的频率，作为自展支持率；④折刀法：类似重采样，但每次去掉部分数据而非有放回抽样；⑤支持率高说明该分支受数据支持较稳定，低支持率提示分支不可靠或数据信息不足。", "points": "点估计需可靠性测度；自展重采样、伪数据集、重复建树；自展支持率；折刀法；支持率高低解释", "mod": 0, "modName": "第十一章 分子进化与系统发育", "level": "掌握", "src": "生成"}]};